fn decorationsVisibleForConfig(value: configpkg.Config.WindowDecoration) bool {
    return value != .none;
}

fn initialDecorationsVisibleForSource(config: *const configpkg.Config, clone_state_from: ?*const Surface) bool {
    if (clone_state_from) |source| return source.decorations_visible;
    return decorationsVisibleForConfig(config.@"window-decoration");
}

fn decorationVisibilityForChromeValue(active_surface_visible: ?bool, cached_visible: bool) bool {
    return active_surface_visible orelse cached_visible;
}

fn startupHostWindowStyle(decorations_visible: bool, fullscreen: bool) u32 {
    return effectiveHostWindowStyle(decorations_visible, fullscreen, true) & ~@as(u32, c.WS_VISIBLE);
}

fn surfaceWindowStyle() u32 {
    // Keep the terminal child surface hidden until GL + core init complete,
    // then show it explicitly from Surface.init.
    return c.WS_CHILD | c.WS_CLIPSIBLINGS;
}

fn effectiveHostWindowStyle(
    decorations_visible: bool,
    fullscreen: bool,
    hosted: bool,
) u32 {
    if (fullscreen) {
        return if (hosted)
            c.WS_VISIBLE | c.WS_POPUP | c.WS_CLIPCHILDREN
        else
            c.WS_VISIBLE | c.WS_POPUP;
    }

    if (decorations_visible) {
        return if (hosted)
            c.WS_VISIBLE | WS_OVERLAPPEDWINDOW | c.WS_CLIPCHILDREN
        else
            c.WS_VISIBLE | WS_OVERLAPPEDWINDOW;
    }

    return if (hosted)
        c.WS_VISIBLE | c.WS_OVERLAPPED | c.WS_CLIPCHILDREN
    else
        c.WS_VISIBLE | c.WS_OVERLAPPED;
}

fn sharesHostWindowState(dst_host_id: ?u32, src_host_id: ?u32) bool {
    return dst_host_id != null and src_host_id != null and dst_host_id.? == src_host_id.?;
}

fn sizeLimitEquals(a: apprt.action.SizeLimit, b: apprt.action.SizeLimit) bool {
    return a.min_width == b.min_width and
        a.min_height == b.min_height and
        a.max_width == b.max_width and
        a.max_height == b.max_height;
}

fn shouldShowSurfaceImmediately(host_id: ?u32) bool {
    return host_id == null;
}

fn shouldActivateSurfaceDuringInit(host_id: ?u32, passive_show: bool) bool {
    return shouldShowSurfaceImmediately(host_id) and !passive_show;
}

fn shouldResizeHostForInitialSize(host_surface_count: usize) bool {
    return host_surface_count == 1;
}

fn sharedHostWindowFrameStateEquals(a: *const Surface, b: *const Surface) bool {
    return effectiveHostWindowStyle(
        a.decorations_visible,
        a.fullscreen,
        true,
    ) == effectiveHostWindowStyle(
        b.decorations_visible,
        b.fullscreen,
        true,
    ) and sizeLimitEquals(a.size_limit, b.size_limit);
}

fn sharedHostWindowTopmostEquals(a: *const Surface, b: *const Surface) bool {
    return a.topmost == b.topmost;
}

fn sharedHostWindowOpacityEquals(a: *const Surface, b: *const Surface) bool {
    return alphaByteForOpacity(effectiveBackgroundOpacity(
        a.background_opacity_default,
        a.background_opacity_force_opaque,
    )) == alphaByteForOpacity(effectiveBackgroundOpacity(
        b.background_opacity_default,
        b.background_opacity_force_opaque,
    ));
}

fn shouldPropagateSharedHostWindowState(source: *const Surface) bool {
    const host = source.host orelse return true;
    return host.activeSurface() == source;
}

fn shouldApplyConfigDecorations(decorations_visible_overridden: bool) bool {
    return !decorations_visible_overridden;
}

fn usesIntegratedTitlebar(
    enabled: bool,
    tab_bar_visible: bool,
    decorations_visible: bool,
) bool {
    return enabled and tab_bar_visible and decorations_visible;
}

fn hostPresentShowCommand(
    is_visible: bool,
    is_iconic: bool,
    is_zoomed: bool,
) ?i32 {
    if (is_iconic) return c.SW_RESTORE;
    if (is_visible) return null;
    return if (is_zoomed) c.SW_MAXIMIZE else c.SW_SHOW;
}

fn intResource(id: usize) INTRESOURCE {
    return @as(INTRESOURCE, @ptrFromInt(id));
}

fn appIconResource() INTRESOURCE {
    return intResource(c.ID_ICON_GHOSTTY);
}

fn loadAppIcon(hinstance: HINSTANCE, small: bool) HICON {
    const cx = if (small) sys.GetSystemMetrics(c.SM_CXSMICON) else sys.GetSystemMetrics(c.SM_CXICON);
    const cy = if (small) sys.GetSystemMetrics(c.SM_CYSMICON) else sys.GetSystemMetrics(c.SM_CYICON);
    return sys.LoadImageW(
        hinstance,
        appIconResource(),
        c.IMAGE_ICON,
        if (cx > 0) cx else if (small) 16 else 32,
        if (cy > 0) cy else if (small) 16 else 32,
        c.LR_SHARED,
    );
}

fn setWindowIcon(hwnd: HWND, hinstance: HINSTANCE) void {
    if (loadAppIcon(hinstance, false)) |icon| {
        _ = sys.SendMessageW(hwnd, c.WM_SETICON, c.ICON_BIG, @as(LPARAM, @bitCast(@intFromPtr(icon))));
    }
    if (loadAppIcon(hinstance, true)) |icon| {
        _ = sys.SendMessageW(hwnd, c.WM_SETICON, c.ICON_SMALL, @as(LPARAM, @bitCast(@intFromPtr(icon))));
    }
}

fn shouldDispatchOcclusion(current: ?bool, visible: bool) bool {
    return current == null or current.? != visible;
}

fn applyProfileSurfaceConfig(
    config: *configpkg.Config,
    profile: *const windows_shell.Profile,
) !void {
    config.@"working-directory" = .home;
    try applyProfileLaunchConfig(config, profile);
}

/// Applies a profile's command plus the kind-specific hardening that has to
/// hold on EVERY launch path — new surface, split, and restore alike. Splits
/// used to apply only the command, which silently dropped the SSH guarantees
/// below, so both paths go through here.
fn applyProfileLaunchConfig(
    config: *configpkg.Config,
    profile: *const windows_shell.Profile,
) !void {
    try applyProfileCommandConfig(config, profile);
    if (profile.kind != .ssh) return;

    // Shell integration injection rewrites the two-element ssh argv into a
    // space-joined, unquoted `cmd.exe /C` string. A remote session cannot use
    // it anyway: the integration scripts run locally.
    config.@"shell-integration" = .none;

    // `.home` alone loses to an inherited working directory, so resolve the
    // path explicitly and let the drive-absolute branch of the cwd resolver
    // take it. This is the same directory `ssh` itself expands `~` to.
    var home_buf: [std.fs.max_path_bytes]u8 = undefined;
    if (try windows_ssh_hosts.userProfileDir(&home_buf)) |home| {
        const alloc = config._arena.?.allocator();
        config.@"working-directory" = .{ .path = try alloc.dupe(u8, home) };
    }
}

fn applyProfileCommandConfig(
    config: *configpkg.Config,
    profile: *const windows_shell.Profile,
) !void {
    const alloc = config._arena.?.allocator();

    // newConfig() returns a shallow clone, so aliased fields such as
    // command remain owned by the source config arena. Replacing command on
    // the clone must not deinit the inherited value.
    config.command = try profile.command.clone(alloc);
}

fn splitWorkingDirectoryCandidate(live_pwd: ?[]const u8, cached_pwd: ?[]const u8) ?[]const u8 {
    if (live_pwd) |pwd| {
        if (pwd.len > 0) return pwd;
    }
    if (cached_pwd) |pwd| {
        if (pwd.len > 0) return pwd;
    }
    return null;
}

fn applySplitWorkingDirectoryPath(
    config: *configpkg.Config,
    source_pwd: ?[]const u8,
) !bool {
    if (!config.@"split-inherit-working-directory") return false;
    const pwd = source_pwd orelse return false;
    if (pwd.len == 0) return false;

    const alloc = config._arena.?.allocator();
    config.@"working-directory" = .{ .path = try alloc.dupe(u8, pwd) };
    return true;
}

fn shouldTreatWslSplitPwdAsStartupFallback(
    alloc: Allocator,
    command: ?configpkg.Command,
    candidate: []const u8,
    startup_cwd: ?[]const u8,
) !bool {
    const cmd = command orelse return false;
    if (!windows_shell.isWslCommand(cmd)) return false;
    const startup = startup_cwd orelse return false;
    if (candidate.len == 0 or startup.len == 0) return false;

    if (std.ascii.eqlIgnoreCase(candidate, startup)) return true;
    const startup_wsl = (try windows_shell.pathToWsl(alloc, startup)) orelse return false;
    defer alloc.free(startup_wsl);
    return std.mem.eql(u8, candidate, startup_wsl);
}

fn applySplitWorkingDirectoryFromSource(
    config: *configpkg.Config,
    source: *Surface,
    startup_cwd: ?[]const u8,
) !bool {
    if (!config.@"split-inherit-working-directory") return false;

    const alloc = config._arena.?.allocator();
    const live_pwd = source.core().pwd(alloc) catch |err| blk: {
        log.warn("win32 split cwd inheritance could not query live cwd err={}", .{err});
        break :blk null;
    };

    if (live_pwd) |pwd| {
        if (try shouldTreatWslSplitPwdAsStartupFallback(
            alloc,
            config.command,
            pwd,
            startup_cwd,
        )) {
            if (source.pwd) |cached| {
                if (cached.len > 0) return try applySplitWorkingDirectoryPath(config, cached);
            }
            config.@"working-directory" = .home;
            return true;
        }
    }

    const candidate = splitWorkingDirectoryCandidate(live_pwd, source.pwd) orelse return false;
    if (live_pwd) |pwd| {
        if (candidate.ptr == pwd.ptr and candidate.len == pwd.len) {
            config.@"working-directory" = .{ .path = pwd };
            return true;
        }
    }
    return try applySplitWorkingDirectoryPath(config, candidate);
}

fn shouldInheritSplitWorkingDirectory(source_launched_ssh: bool) bool {
    return !source_launched_ssh;
}

fn defaultIpcNamespace() []const u8 {
    return if (builtin.mode == .Debug)
        "io.github.amanthanvi.noctty-debug"
    else
        "io.github.amanthanvi.noctty";
}

fn sanitizeIpcNamespace(alloc: Allocator, raw: ?[]const u8) ![]const u8 {
    const trimmed = std.mem.trim(u8, raw orelse defaultIpcNamespace(), &std.ascii.whitespace);
    const source = if (trimmed.len == 0) defaultIpcNamespace() else trimmed;

    var buf: std.ArrayList(u8) = .empty;
    errdefer buf.deinit(alloc);

    for (source) |char| {
        if (std.ascii.isAlphanumeric(char) or char == '.' or char == '-' or char == '_') {
            try buf.append(alloc, char);
        } else {
            try buf.append(alloc, '_');
        }
    }

    if (buf.items.len == 0) try buf.appendSlice(alloc, defaultIpcNamespace());
    return try buf.toOwnedSlice(alloc);
}

fn allocIpcPipeName(alloc: Allocator, raw_namespace: ?[]const u8) ![:0]const u16 {
    const namespace = try sanitizeIpcNamespace(alloc, raw_namespace);
    defer alloc.free(namespace);

    const pipe_name_utf8 = try std.fmt.allocPrint(alloc, "{s}{s}", .{
        ipc_pipe_prefix,
        namespace,
    });
    defer alloc.free(pipe_name_utf8);

    return try std.unicode.utf8ToUtf16LeAllocZ(alloc, pipe_name_utf8);
}

fn resolveIpcPipeNameForTarget(
    alloc: Allocator,
    target: apprt.ipc.Target,
) ![:0]const u16 {
    return switch (target) {
        .class => |class| allocIpcPipeName(alloc, class),
        .detect => allocIpcPipeName(alloc, null),
    };
}

/// Connect to the single-instance IPC pipe as a client.
///
/// `error.FileNotFound` and `error.PipeUnreachable` both mean "there is no
/// instance we can talk to"; callers must treat them the same and fall back
/// to running locally. They are kept distinct only so the unreachable case
/// can be logged differently.
/// Backing store for a copied SID. `SECURITY_MAX_SID_SIZE` is 68 bytes, so
/// 256 is ample. The alignment is required, not cosmetic: a `SID` ends in an
/// array of `DWORD` sub-authorities, and `EqualSid` reads them as such.
const SidBuffer = [256]u8;
const sid_buffer_align = @alignOf(u32);

/// Copy the current process token's user SID into `buf`, returning the
/// populated prefix.
fn currentUserSidBytes(buf: *align(sid_buffer_align) SidBuffer) ![]u8 {
    var token: windows.HANDLE = undefined;
    if (sys.OpenProcessToken(
        windows.kernel32.GetCurrentProcess(),
        c.TOKEN_QUERY,
        &token,
    ) == 0) return error.TokenQueryFailed;
    defer _ = windows.CloseHandle(token);
    return try tokenUserSidBytes(token, buf);
}

fn tokenUserSidBytes(
    token: windows.HANDLE,
    buf: *align(sid_buffer_align) SidBuffer,
) ![]u8 {
    var token_user_buf: [256]u8 align(@alignOf(sys.TOKEN_USER)) = undefined;
    var token_user_len: u32 = 0;
    if (sys.GetTokenInformation(
        token,
        c.TokenUser,
        &token_user_buf,
        token_user_buf.len,
        &token_user_len,
    ) == 0) return error.TokenQueryFailed;

    const token_user: *const sys.TOKEN_USER = @ptrCast(&token_user_buf);
    const sid_len = sys.GetLengthSid(token_user.User.Sid);
    if (sid_len == 0 or sid_len > buf.len) return error.TokenQueryFailed;

    const sid_bytes: [*]const u8 = @ptrCast(token_user.User.Sid);
    @memcpy(buf[0..sid_len], sid_bytes[0..sid_len]);
    return buf[0..sid_len];
}

/// Mandatory integrity level of a token, as an `S-1-16-<rid>` RID.
///
/// Unlike `allocIpcPipeIntegritySid` this reports EVERY level including
/// medium and below, because the comparison below needs the actual value
/// rather than "is it above medium".
fn tokenIntegrityRid(token: windows.HANDLE) ?u32 {
    var label_buf: [256]u8 align(@alignOf(sys.TOKEN_MANDATORY_LABEL)) = undefined;
    var label_len: u32 = 0;
    if (sys.GetTokenInformation(
        token,
        c.TokenIntegrityLevel,
        &label_buf,
        label_buf.len,
        &label_len,
    ) == 0) return null;
    const label: *const sys.TOKEN_MANDATORY_LABEL = @ptrCast(&label_buf);

    var sid_string: ?[*:0]u16 = null;
    if (sys.ConvertSidToStringSidW(label.Label.Sid, &sid_string) == 0) return null;
    const sid = sid_string orelse return null;
    defer _ = sys.LocalFree(@ptrCast(sid));

    return integrityRidFromSidString(std.mem.span(sid));
}

/// Is this connected pipe object owned and labelled for our trust level?
///
/// The single-instance pipe name is derived only from `--class`, so it is
/// PREDICTABLE and lives in the machine-wide named-pipe namespace. Any local
/// account can therefore pre-create `\\.\pipe\noctty.<class>` before we do.
/// The server-side owner-only DACL does not help here: it protects the pipe
/// WE create, not the one we CONNECT to. Without this check a squatter would
/// receive our forwarded startup arguments (including the working directory)
/// and could return a forged ack, so the real instance never starts and the
/// user gets no window -- a cross-account disclosure plus a startup denial.
///
/// This runs before the first write. `ImpersonateNamedPipeClient` is
/// documented to impersonate "the security context of the last message read
/// from the pipe", so a server that has read nothing from us has no context
/// to assume. That ordering is a defence in depth rather than the guarantee,
/// though: the guarantee is that `connectToIpcPipe` opens with
/// `SECURITY_SQOS_PRESENT | SECURITY_IDENTIFICATION`, which caps the server
/// at an identification-only token whatever the timing.
///
/// Authentication is read from the descriptor attached to THIS pipe object.
/// A PID lookup is not sufficient: a duplicated server handle can outlive
/// its creating process, and the numeric PID can then be recycled.
///
/// Fails CLOSED: any query or parse error answers "not ours".
fn ipcPipeServerIsTrusted(pipe: windows.HANDLE) bool {
    const information = c.OWNER_SECURITY_INFORMATION | c.LABEL_SECURITY_INFORMATION;
    var owner: ?*anyopaque = null;
    var descriptor: ?*anyopaque = null;
    if (sys.GetSecurityInfo(
        pipe,
        c.SE_KERNEL_OBJECT,
        information,
        &owner,
        null,
        null,
        null,
        &descriptor,
    ) != 0) return false;
    const attached = descriptor orelse return false;
    defer _ = sys.LocalFree(attached);

    var own_buf: SidBuffer align(sid_buffer_align) = undefined;
    const own_sid = currentUserSidBytes(&own_buf) catch return false;
    if (owner == null or sys.EqualSid(owner.?, @ptrCast(own_sid.ptr)) == 0) return false;

    // The user SID is NOT sufficient on its own. Under the ordinary split
    // UAC token, an elevated process and a medium-integrity process of the
    // same account carry the SAME user SID, so `EqualSid` alone would let a
    // medium-integrity squatter pre-create the predictable name and serve an
    // ELEVATED client -- which would then hand its forwarded arguments
    // downward and accept a forged ack. `SECURITY_IDENTIFICATION` prevents
    // the squatter impersonating us; it says nothing about who it is.
    //
    // So require the server to be at least our own integrity level. Equal is
    // fine (the normal case, and what the medium-to-medium path needs);
    // higher is fine (a medium client talking to an elevated instance is
    // already governed by the pipe's NO_WRITE_UP label); strictly lower is
    // refused.
    var own_token: windows.HANDLE = undefined;
    if (sys.OpenProcessToken(
        windows.kernel32.GetCurrentProcess(),
        c.TOKEN_QUERY,
        &own_token,
    ) == 0) return false;
    defer _ = windows.CloseHandle(own_token);

    const own_rid = tokenIntegrityRid(own_token) orelse return false;
    const server_rid = descriptorIntegrityRid(attached) catch return false;
    return server_rid >= own_rid;
}

fn descriptorIntegrityRid(descriptor: *anyopaque) error{InvalidSecurityDescriptor}!u32 {
    var text: ?[*:0]u16 = null;
    if (sys.ConvertSecurityDescriptorToStringSecurityDescriptorW(
        descriptor,
        c.SDDL_REVISION_1,
        c.LABEL_SECURITY_INFORMATION,
        &text,
        null,
    ) == 0) return error.InvalidSecurityDescriptor;
    const text_ptr = text orelse return error.InvalidSecurityDescriptor;
    defer _ = sys.LocalFree(@ptrCast(text_ptr));

    return descriptorIntegrityRidFromSddl(std.mem.span(text_ptr));
}

fn descriptorIntegrityRidFromSddl(sddl: []const u16) error{InvalidSecurityDescriptor}!u32 {
    const prefix = std.unicode.utf8ToUtf16LeStringLiteral("S-1-16-");
    if (std.mem.indexOf(u16, sddl, prefix)) |start| {
        var rid: u32 = 0;
        var digits: usize = 0;
        for (sddl[start + prefix.len ..]) |ch| {
            if (ch < '0' or ch > '9') break;
            rid = std.math.mul(u32, rid, 10) catch return error.InvalidSecurityDescriptor;
            rid = std.math.add(u32, rid, ch - '0') catch return error.InvalidSecurityDescriptor;
            digits += 1;
        }
        if (digits == 0) return error.InvalidSecurityDescriptor;
        return rid;
    }

    // Windows renders well-known mandatory-label SIDs using SDDL aliases.
    // The label-only descriptor contains no unrelated ACEs, so matching the
    // trustee suffix is unambiguous.
    const aliases = [_]struct { suffix: []const u16, rid: u32 }{
        .{ .suffix = std.unicode.utf8ToUtf16LeStringLiteral(";;;UN)"), .rid = 0x0000 },
        .{ .suffix = std.unicode.utf8ToUtf16LeStringLiteral(";;;LW)"), .rid = 0x1000 },
        .{ .suffix = std.unicode.utf8ToUtf16LeStringLiteral(";;;ME)"), .rid = 0x2000 },
        .{ .suffix = std.unicode.utf8ToUtf16LeStringLiteral(";;;MP)"), .rid = 0x2100 },
        .{ .suffix = std.unicode.utf8ToUtf16LeStringLiteral(";;;HI)"), .rid = 0x3000 },
        .{ .suffix = std.unicode.utf8ToUtf16LeStringLiteral(";;;SI)"), .rid = 0x4000 },
    };
    for (aliases) |alias| {
        if (std.mem.indexOf(u16, sddl, alias.suffix) != null) return alias.rid;
    }

    // The producer always emits an explicit label. Missing or unknown labels
    // must fail closed; otherwise a low-integrity same-user squatter can rely
    // on Windows' implicit-medium interpretation and impersonate our server.
    if (std.mem.indexOf(u16, sddl, std.unicode.utf8ToUtf16LeStringLiteral("(ML;")) != null) {
        return error.InvalidSecurityDescriptor;
    }
    return error.InvalidSecurityDescriptor;
}

fn connectToIpcPipe(pipe_name: [:0]const u16) !windows.HANDLE {
    var retries: u8 = 0;
    while (true) {
        const handle = windows.kernel32.CreateFileW(
            pipe_name.ptr,
            windows.GENERIC_READ | windows.GENERIC_WRITE,
            0,
            null,
            windows.OPEN_EXISTING,
            // Deny impersonation outright rather than relying on the server
            // never having read a message from us. See the constants.
            windows.FILE_ATTRIBUTE_NORMAL |
                c.SECURITY_SQOS_PRESENT |
                c.SECURITY_IDENTIFICATION,
            null,
        );
        if (handle != windows.INVALID_HANDLE_VALUE) {
            if (!ipcPipeServerIsTrusted(handle)) {
                _ = windows.CloseHandle(handle);
                log.warn(
                    "single-instance pipe owner or integrity label is not trusted; " ++
                        "refusing to forward anything to it",
                    .{},
                );
                return error.PipeUnreachable;
            }
            return handle;
        }

        const err = windows.kernel32.GetLastError();
        switch (err) {
            .FILE_NOT_FOUND => return error.FileNotFound,

            // The pipe exists but this token may not open it. The common
            // cause is an elevated instance holding the name: its descriptor
            // carries a NO_WRITE_UP mandatory label, so a medium-integrity
            // client is denied at CreateFileW. That is the intended denial,
            // but it must NOT abort startup -- an ordinary non-elevated
            // launch has to fall through to its own local instance rather
            // than failing to open a window at all.
            .ACCESS_DENIED => return error.PipeUnreachable,

            .PIPE_BUSY => {
                if (retries == 0 and sys.WaitNamedPipeW(pipe_name.ptr, 1000) != 0) {
                    retries += 1;
                    continue;
                }
                return error.PipeBusy;
            },
            else => return windows.unexpectedError(err),
        }
    }
}

fn sendNewWindowIpc(
    alloc: Allocator,
    pipe_name: [:0]const u16,
    arguments: ?[]const [:0]const u8,
) !bool {
    const pipe = connectToIpcPipe(pipe_name) catch |err| switch (err) {
        error.FileNotFound => return false,
        // No instance we are allowed to talk to. Report "not forwarded" so
        // the caller starts a local instance instead of aborting startup.
        error.PipeUnreachable => {
            log.info(
                "single-instance pipe exists but is not accessible to this token; starting a local instance",
                .{},
            );
            return false;
        },
        error.PipeBusy => return error.IPCFailed,
        else => return err,
    };
    defer _ = windows.CloseHandle(pipe);

    const request = try win32_ipc.encodeNewWindowRequest(alloc, arguments);
    defer alloc.free(request);

    try win32_ipc.writeAll(pipe, request);
    return try win32_ipc.readAck(pipe);
}

fn sendListWindowsIpc(
    alloc: Allocator,
    pipe_name: [:0]const u16,
) !?[]u8 {
    const pipe = connectToIpcPipe(pipe_name) catch |err| switch (err) {
        // Both mean "no instance we can reach"; see `connectToIpcPipe`.
        error.FileNotFound, error.PipeUnreachable => return null,
        error.PipeBusy => return error.IPCFailed,
        else => return err,
    };
    defer _ = windows.CloseHandle(pipe);

    const request = try win32_ipc.encodeListWindowsRequest(alloc);
    defer alloc.free(request);

    try win32_ipc.writeAll(pipe, request);
    return try win32_ipc.readDataResponseWithTimeout(
        alloc,
        pipe,
        win32_ipc.automation_response_timeout_ms,
    );
}

fn sendPerformActionIpc(
    alloc: Allocator,
    pipe_name: [:0]const u16,
    target: apprt.ipc.AutomationActionTarget,
    action_text: []const u8,
) !bool {
    const pipe = connectToIpcPipe(pipe_name) catch |err| switch (err) {
        // Both mean "no instance we can reach"; see `connectToIpcPipe`.
        error.FileNotFound, error.PipeUnreachable => return false,
        error.PipeBusy => return error.IPCFailed,
        else => return err,
    };
    defer _ = windows.CloseHandle(pipe);

    const request = try win32_ipc.encodePerformActionRequest(alloc, target, action_text);
    defer alloc.free(request);

    try win32_ipc.writeAll(pipe, request);
    return try win32_ipc.readAckWithTimeout(pipe, win32_ipc.automation_response_timeout_ms);
}

/// Configuration keys a forwarded `new_window` argv is allowed to set.
///
/// `applyNewWindowArguments` runs on the SERVER side of the single-instance
/// IPC pipe and feeds caller-controlled argv straight into `Config.loadIter`,
/// so the automation allowlist in `App.isSafeAutomationAction` is not the
/// boundary for this request kind. Any process running as this user can write
/// to the pipe, so this argv must be treated as untrusted input.
///
/// This is an ALLOWLIST, deliberately, and not a denylist. The config surface
/// is ~190 fields and grows with every upstream merge; a denylist gets it
/// wrong by omission every time a new key lands. Deny-by-default means an
/// unrecognised key -- including any key added upstream after this list was
/// written -- is refused until someone reviews it.
///
/// Admission rule: a key qualifies only if its value is a scalar, an enum, a
/// color, or (for `title`) a display string that is sanitized downstream. A
/// key does NOT qualify if its value is resolved as a filesystem path, a
/// command, an environment variable, a font or theme NAME looked up against
/// something, an additional configuration source, or bytes that can reach the
/// pty. That rule excludes, among others:
///
///   - `command`, `initial-command`, `-e`  -> become the spawned child.
///   - `input`                             -> written straight to the pty;
///     its own doc comment warns it can execute programs in a shell.
///   - `env`                               -> overrides are applied AFTER
///     `shell_integration.setup`, so `ZDOTDIR` / `ENV` / `XDG_DATA_DIRS` /
///     `GHOSTTY_BASH_RCFILE` / `PATH` become code execution at shell start.
///   - `config-file`, `config-default-files`, `theme` -> config sources.
///     `theme` accepts an absolute path and is parsed as a full config file
///     (`config/theme.zig` `open`), so it is a `config-file` by proxy.
///   - `background-image`, `bell-audio-path`, `custom-shader`,
///     `gtk-custom-css`                    -> arbitrary file reads, and UNC
///     values make this process authenticate to a remote SMB host.
///   - `keybind`, `command-palette-entry`  -> inject attacker-chosen binding
///     actions, re-opening the `.perform_action` allowlist by another door.
///   - `enquiry-response`                  -> attacker bytes written to the
///     pty when the child sends ENQ.
///   - `title-report`, `window-save-state`, `class` -> not presentation.
///   - `font-family*`, `font-style*`, `font-feature`, `font-variation*`,
///     `font-codepoint-map`, `window-title-font-family` -> name strings that
///     are resolved by font discovery. Excluded on the admission rule rather
///     than because a concrete exploit is known.
///
/// `working-directory` is handled separately: it is admitted, but its VALUE
/// is constrained by `forwardedWorkingDirectoryAllowed`.
const forwarded_argv_allowed_keys = [_][]const u8{
    // Window geometry, decoration, and state.
    "window-width",
    "window-height",
    "window-position-x",
    "window-position-y",
    "window-padding-x",
    "window-padding-y",
    "window-padding-balance",
    "window-padding-color",
    "window-decoration",
    "window-theme",
    "window-colorspace",
    "window-subtitle",
    "window-titlebar-background",
    "window-titlebar-foreground",
    "window-show-tab-bar",
    "window-new-tab-position",
    "window-step-resize",
    "window-vsync",
    "maximize",
    "fullscreen",
    "title",

    // Font sizing and rendering. Font NAME keys are deliberately absent.
    "font-size",
    "font-thicken",
    "font-thicken-strength",
    "font-synthetic-style",
    "font-shaping-break",

    // Colors and compositing.
    "background",
    "foreground",
    "palette",
    "selection-foreground",
    "selection-background",
    "cursor-color",
    "cursor-text",
    "cursor-style",
    "cursor-style-blink",
    "cursor-opacity",
    "background-opacity",
    "background-opacity-cells",
    "background-blur",
    "unfocused-split-opacity",
    "unfocused-split-fill",
    "split-divider-color",
    "bold-color",
    "faint-opacity",
    "minimum-contrast",
    "alpha-blending",
};

/// The one allowlisted key whose value needs its own check.
const forwarded_working_directory_key = "working-directory";

/// Extract the config key from a forwarded argument, or null when the
/// argument is not in `--key[=value]` form.
///
/// `cli/args.zig` (:112-133) takes `key = arg[2..]` up to the first `=` and
/// matches it with exact case-sensitive `mem.eql` against field names. There
/// is no prefix abbreviation, no `--key value` separate-token form, no case
/// folding, and no underscore/hyphen aliasing, so this sees exactly the key
/// the loader will act on.
fn forwardedArgumentKey(arg: []const u8) ?[]const u8 {
    if (!std.mem.startsWith(u8, arg, "--")) return null;
    const body = arg[2..];
    return if (std.mem.indexOfScalar(u8, body, '=')) |idx| body[0..idx] else body;
}

/// True when a forwarded config key is on the allowlist. `working-directory`
/// is included here; its value is checked separately.
fn forwardedKeyAllowed(key: []const u8) bool {
    if (std.mem.eql(u8, key, forwarded_working_directory_key)) return true;
    for (forwarded_argv_allowed_keys) |allowed| {
        if (std.mem.eql(u8, key, allowed)) return true;
    }
    return false;
}

/// True when a key is safe to echo into a log line.
///
/// The refused key comes from the pipe, so it is attacker-controlled text and
/// must not be logged raw (newlines would forge log records). Real config keys
/// are lowercase ASCII with hyphens and digits, so anything else is reported
/// generically instead.
fn forwardedKeyLoggable(key: []const u8) bool {
    if (key.len == 0 or key.len > 64) return false;
    for (key) |ch| {
        const ok = (ch >= 'a' and ch <= 'z') or
            (ch >= '0' and ch <= '9') or
            ch == '-';
        if (!ok) return false;
    }
    return true;
}

/// Returns true when a forwarded `--working-directory` value is one the
/// server is willing to honor.
///
/// The startup forwarder always sends the launching process's realpath'd cwd
/// (`collectStartupForwardArguments`), so this key cannot be rejected
/// outright without breaking every single-instance launch. It is instead
/// constrained to the symbolic values, a home-relative path, or a local
/// drive-letter absolute path.
///
/// SCOPE OF THIS CHECK, stated precisely: it rejects UNC *syntax* only. A
/// mapped drive (`net use Z: \\host\share`), a `subst` drive, or a junction
/// under a local drive still resolves off-box, and any same-user process can
/// create those. That is acceptable under this channel's threat model --
/// same-user code is already trusted -- and the point of the check is to stop
/// a bare `\\attacker\share` value from making the server authenticate to an
/// attacker-chosen SMB host.
///
/// The check is deliberately PURELY SYNTACTIC. An earlier version called
/// `openDirAbsolute` to confirm the directory existed, but that resolution is
/// itself the SMB authentication we are trying to avoid for mapped drives and
/// junctions, and it was defeated by TOCTOU anyway since the path is
/// re-resolved at spawn time.
fn forwardedWorkingDirectoryAllowed(value: []const u8) bool {
    var trimmed = std.mem.trim(u8, value, &std.ascii.whitespace);

    // `Config.parseCLI` strips one pair of surrounding double quotes, so a
    // quoted path is a legal value and must not be refused here.
    if (trimmed.len >= 2 and trimmed[0] == '"' and trimmed[trimmed.len - 1] == '"') {
        trimmed = std.mem.trim(u8, trimmed[1 .. trimmed.len - 1], &std.ascii.whitespace);
    }

    if (std.mem.eql(u8, trimmed, "home")) return true;
    if (std.mem.eql(u8, trimmed, "inherit")) return true;

    // `~`, `~/...` and `~\...` are documented legal values that
    // `WorkingDirectory.finalize` expands against the user's own home
    // directory, so they cannot point off-box.
    if (std.mem.eql(u8, trimmed, "~")) return true;
    if (trimmed.len >= 2 and trimmed[0] == '~' and
        (trimmed[1] == '/' or trimmed[1] == '\\')) return true;

    // Everything else must be a local drive-letter absolute path. This
    // rejects UNC (`\\host\share`, `//host/share`), device namespace
    // (`\\?\`, `\\.\`), relative (`foo\bar`) and drive-relative (`C:foo`).
    if (trimmed.len < 3) return false;
    if (!std.ascii.isAlphabetic(trimmed[0])) return false;
    if (trimmed[1] != ':') return false;
    if (trimmed[2] != '\\' and trimmed[2] != '/') return false;
    return true;
}

/// Why a forwarded argv was refused. `key` borrows from the argument and is
/// only safe to log when `forwardedKeyLoggable(key)`.
const ForwardedArgvRejection = struct {
    reason: enum { not_allowlisted, bad_working_directory, not_a_config_flag },
    key: []const u8,
};

/// Scan a forwarded `new_window` argv and describe the first argument that
/// must not be honored, or null when every argument is acceptable.
///
/// Every element is scanned, so a repeated or trailing occurrence of a key
/// cannot slip past by appearing after an acceptable one.
fn forwardedArgvRejection(argv: []const [:0]const u8) ?ForwardedArgvRejection {
    for (argv) |arg| {
        const key = forwardedArgumentKey(arg) orelse {
            // Not `--key[=value]`. `-e` lands here, and
            // `Config.parseManuallyHook` would turn it into
            // `initial-command`. Nothing in this form is ever legitimate on
            // a forwarded argv, so refuse rather than relying on the loader
            // to treat it as an inert diagnostic.
            return .{ .reason = .not_a_config_flag, .key = arg };
        };

        if (!forwardedKeyAllowed(key)) {
            return .{ .reason = .not_allowlisted, .key = key };
        }

        if (std.mem.eql(u8, key, forwarded_working_directory_key)) {
            const value = if (std.mem.indexOfScalar(u8, arg, '=')) |idx|
                arg[idx + 1 ..]
            else
                "";
            if (!forwardedWorkingDirectoryAllowed(value)) {
                return .{ .reason = .bad_working_directory, .key = key };
            }
        }
    }
    return null;
}

/// Log a refused forwarded argv at error level, without echoing untrusted
/// text into the log.
fn logForwardedArgvRejection(rejection: ForwardedArgvRejection) void {
    switch (rejection.reason) {
        .bad_working_directory => log.err(
            "refusing forwarded new-window argv: working-directory must be home, inherit, ~/..., or a local absolute path",
            .{},
        ),
        .not_a_config_flag => log.err(
            "refusing forwarded new-window argv: contains an argument that is not a --key=value config flag",
            .{},
        ),
        .not_allowlisted => if (forwardedKeyLoggable(rejection.key)) log.err(
            "refusing forwarded new-window argv: key {s} is not permitted over IPC",
            .{rejection.key},
        ) else log.err(
            "refusing forwarded new-window argv: contains a key that is not permitted over IPC",
            .{},
        ),
    }
}

fn sendLaunchLayoutIpc(
    alloc: Allocator,
    pipe_name: [:0]const u16,
    name: []const u8,
) !bool {
    // Validate before probing the pipe. The caller uses `false` as the cold
    // start fallback, so connecting first would let an invalid name spawn an
    // otherwise ordinary window when no instance is listening.
    const request = try win32_ipc.encodeLaunchLayoutRequest(alloc, name);
    defer alloc.free(request);

    const pipe = connectToIpcPipe(pipe_name) catch |err| switch (err) {
        error.FileNotFound, error.PipeUnreachable => return false,
        error.PipeBusy => return error.IPCFailed,
        else => return err,
    };
    defer _ = windows.CloseHandle(pipe);

    try win32_ipc.writeAll(pipe, request);
    return try win32_ipc.readAckWithTimeout(pipe, win32_ipc.automation_response_timeout_ms);
}

fn trySendStartupLaunchLayoutIpc(
    alloc: Allocator,
    pipe_name: [:0]const u16,
    name: ?[]const u8,
) !?bool {
    const layout_name = name orelse return null;
    return try sendLaunchLayoutIpc(alloc, pipe_name, layout_name);
}

const LaunchLayoutIpcArgument = union(enum) {
    none,
    name: []const u8,
};

fn scanLaunchLayoutIpcArgument(
    arguments: ?[]const [:0]const u8,
) !LaunchLayoutIpcArgument {
    const argv = arguments orelse return .none;
    const prefix = "--launch-layout=";
    var name: ?[]const u8 = null;
    for (argv) |arg| {
        // Config parsing treats everything after -e as command payload.
        // Match that boundary so a child command may legitimately receive an
        // argument that looks like a Noctty layout option.
        if (std.mem.eql(u8, arg, "-e")) break;
        if (!std.mem.startsWith(u8, arg, prefix)) continue;
        if (name != null) return error.MixedLaunchLayoutArguments;
        name = arg[prefix.len..];
    }

    if (name) |value| {
        if (argv.len != 1) return error.MixedLaunchLayoutArguments;
        return .{ .name = value };
    }
    return .none;
}

/// Apply a forwarded `new_window` argv to `config`.
///
/// Returns `error.ForbiddenForwardedArgument` for the whole request if any
/// argument is rejected. Dropping individual keys silently would leave the
/// caller with a window that does not match what was asked for, and would
/// make an attacker's probe indistinguishable from a normal launch.
///
/// This function does not log, so that it stays a pure predicate over argv
/// and can be unit tested; every caller logs the rejection it handles.
fn applyNewWindowArguments(
    alloc_gpa: Allocator,
    config: *configpkg.Config,
    arguments: ?[]const [:0]const u8,
) !void {
    const argv = arguments orelse return;
    if (argv.len == 0) return;

    if (forwardedArgvRejection(argv) != null) {
        return error.ForbiddenForwardedArgument;
    }

    // This clone inherits the app config's replay history, and `+new-window`
    // always forwards at least a working directory, so the `finalize` below
    // always runs. `launch-layout` is one-shot: an inherited startup step
    // replayed here would turn an ordinary new window into a layout launch.
    _ = config.dropLaunchLayoutReplaySteps(0);
    config.@"launch-layout" = null;

    var iter: ForwardedArgIterator = .{ .args = argv };
    try config.loadIter(alloc_gpa, &iter);
    try config.finalize();
}

fn normalizeForwardedStartupArg(
    alloc: Allocator,
    arg: []const u8,
) !?[:0]const u8 {
    if (std.mem.startsWith(u8, arg, "--class=") or
        std.mem.startsWith(u8, arg, "--single-instance=") or
        std.mem.startsWith(u8, arg, "--gtk-single-instance=") or
        std.mem.eql(u8, arg, "--safe-mode"))
    {
        return null;
    }

    // Action Center launches carry the target as a positional URI. Preserve
    // only a URI that the same parser used by the receiver accepts; malformed
    // lookalikes still fall through to the non-flag rejection below.
    if (win32_toast_activation.parseLaunchArg(arg)) |_| {
        return try alloc.dupeZ(u8, arg);
    } else |_| {}

    // Drop anything the running instance would refuse, so an ordinary launch
    // still gets a window instead of having the whole request rejected. This
    // is a usability measure on OUR OWN argv, not a security control -- the
    // server re-checks every argument, because a hostile pipe writer never
    // runs this code.
    const key = forwardedArgumentKey(arg) orelse {
        log.warn("not forwarding non-flag startup argument to the running instance", .{});
        return null;
    };
    if (!forwardedKeyAllowed(key)) {
        log.warn(
            "not forwarding {s} to the running instance: it may not be set over IPC",
            .{key},
        );
        return null;
    }

    if (std.mem.startsWith(u8, arg, "--working-directory=")) {
        const raw = arg["--working-directory=".len..];
        const trimmed = std.mem.trim(u8, raw, &std.ascii.whitespace);
        if (std.mem.eql(u8, trimmed, "home") or std.mem.eql(u8, trimmed, "inherit")) {
            return try alloc.dupeZ(u8, arg);
        }

        const cwd = std.fs.cwd();
        var home_buf: [std.fs.max_path_bytes]u8 = undefined;
        const expanded = homedir.expandHome(trimmed, &home_buf) catch trimmed;
        var realpath_buf: [std.fs.max_path_bytes]u8 = undefined;
        const normalized = cwd.realpath(expanded, &realpath_buf) catch expanded;

        // The key check above is not enough for this one option: the server
        // refuses the ENTIRE argv on a bad working-directory VALUE, and it
        // has already acknowledged the request by then, so the launching
        // process exits having produced no window at all. Dropping just this
        // argument here is what makes the "still gets a window" promise
        // above true for `--working-directory=\\host\share` and friends.
        return try allocForwardedWorkingDirectoryArg(alloc, normalized);
    }

    return try alloc.dupeZ(u8, arg);
}

fn allocForwardedWorkingDirectoryArg(
    alloc: Allocator,
    value: []const u8,
) !?[:0]const u8 {
    if (!forwardedWorkingDirectoryAllowed(value)) {
        log.warn(
            "not forwarding --working-directory to the running instance: " ++
                "value is not a local absolute path",
            .{},
        );
        return null;
    }

    return try std.fmt.allocPrintSentinel(
        alloc,
        "--working-directory={s}",
        .{value},
        0,
    );
}

fn collectStartupForwardArguments(alloc: Allocator) !?[]const [:0]const u8 {
    var iter = try cli_args.argsIterator(alloc);
    defer iter.deinit();

    var argv: std.ArrayList([:0]const u8) = .empty;
    var working_directory_seen = false;
    errdefer {
        for (argv.items) |arg| alloc.free(arg);
        argv.deinit(alloc);
    }

    while (iter.next()) |arg| {
        if (std.mem.startsWith(u8, arg, "--working-directory=")) {
            working_directory_seen = true;
        }
        if (try normalizeForwardedStartupArg(alloc, arg)) |normalized| {
            try argv.append(alloc, normalized);
        }
    }

    if (!working_directory_seen) {
        const cwd = std.fs.cwd();
        var cwd_buf: [std.fs.max_path_bytes]u8 = undefined;
        const wd = try cwd.realpath(".", &cwd_buf);
        if (try allocForwardedWorkingDirectoryArg(alloc, wd)) |arg| {
            try argv.insert(alloc, 0, arg);
        }
    }

    if (argv.items.len == 0) {
        argv.deinit(alloc);
        return null;
    }

    return try argv.toOwnedSlice(alloc);
}

/// Parse the relative identifier out of an integrity-level SID string of the
/// form `S-1-16-<rid>`. Returns null for anything that is not a mandatory
/// label SID, so callers fail closed rather than mislabelling the pipe.
fn integrityRidFromSidString(sid: []const u16) ?u32 {
    const prefix = std.unicode.utf8ToUtf16LeStringLiteral("S-1-16-");
    if (sid.len <= prefix.len) return null;
    if (!std.mem.eql(u16, sid[0..prefix.len], prefix)) return null;

    var rid: u32 = 0;
    for (sid[prefix.len..]) |unit| {
        if (unit < '0' or unit > '9') return null;
        rid = std.math.mul(u32, rid, 10) catch return null;
        rid = std.math.add(u32, rid, @intCast(unit - '0')) catch return null;
    }
    return rid;
}

/// Render the SDDL text for the IPC pipe security descriptor into `buf`.
///
/// `D:P` is a protected DACL (no inherited ACEs) holding exactly one ACE:
/// `GENERIC_ALL` for `user_sid`. An explicit mandatory-label ACE with the
/// `NO_WRITE_UP` policy is always appended, which both prevents write-up and
/// lets clients reject unlabeled same-user squatters.
///
/// RESIDUAL: `NO_WRITE_UP` does not deny reads, so a medium-integrity
/// process can open an elevated instance's pipe for `GENERIC_READ` (a bare
/// `READ_CONTROL` suffices). `WriteFile` on that handle then fails with
/// `win32=5`, so this is an OCCUPANCY problem, not an access break —
/// nothing is disclosed and no request can be submitted. But the server
/// offers one pipe instance at a time, so one such open makes the next
/// legitimate client fail with `win32=231 ERROR_PIPE_BUSY`. All of this is
/// observed on hardware, not inferred.
///
/// The fix is `NO_READ_UP`, and it lands with the elevation work rather
/// than here: that change labels the elevated endpoint `NWNR`, and the
/// added `NR` has been verified on hardware to deny every medium open
/// including `GENERIC_READ` and `READ_CONTROL`. Duplicating it here would
/// collide on the same SDDL term for no net gain, and would invalidate the
/// live descriptor readback recorded in docs/windows.md.
fn buildIpcPipeSddl(
    buf: []u16,
    user_sid: []const u16,
    integrity_sid: []const u16,
) error{IpcSecurityDescriptorFailed}![:0]u16 {
    var len: usize = 0;

    const Appender = struct {
        fn append(dest: []u16, at: *usize, text: []const u16) error{IpcSecurityDescriptorFailed}!void {
            // Reserve one unit for the sentinel.
            if (text.len + 1 > dest.len - at.*) return error.IpcSecurityDescriptorFailed;
            @memcpy(dest[at.*..][0..text.len], text);
            at.* += text.len;
        }
    };

    try Appender.append(buf, &len, std.unicode.utf8ToUtf16LeStringLiteral("O:"));
    try Appender.append(buf, &len, user_sid);
    try Appender.append(buf, &len, std.unicode.utf8ToUtf16LeStringLiteral("D:P(A;;GA;;;"));
    try Appender.append(buf, &len, user_sid);
    try Appender.append(buf, &len, std.unicode.utf8ToUtf16LeStringLiteral(")"));

    try Appender.append(buf, &len, std.unicode.utf8ToUtf16LeStringLiteral("S:(ML;;NW;;;"));
    try Appender.append(buf, &len, integrity_sid);
    try Appender.append(buf, &len, std.unicode.utf8ToUtf16LeStringLiteral(")"));

    buf[len] = 0;
    return buf[0..len :0];
}

/// Resolve the process token's mandatory integrity level as an SDDL SID
/// string at every integrity level.
///
/// Windows does not auto-label kernel objects created by a high-integrity
/// process, and an unlabeled object evaluates as medium. Because the token
/// USER SID is identical across the elevated and non-elevated tokens of one
/// account, a DACL keyed on that SID alone would let a filtered medium-IL
/// process drive an elevated instance's pipe. Returning the label SID here
/// lets the caller add `S:(ML;;NW;;;S-1-16-<rid>)`, which blocks write-up.
///
/// RESIDUAL: the policy is `NW` only, not `NR`/`NX`. See the fuller note on
/// `buildIpcPipeSddl`; in short, and now measured rather than assumed, a
/// medium-integrity process can open an elevated instance's pipe for
/// `GENERIC_READ` -- a bare `READ_CONTROL` is enough, it need not request
/// read data access at all -- and `WriteFile` on that handle then fails
/// `win32=5`. So this is an OCCUPANCY problem, not an access break, but the
/// server offers one pipe instance at a time, so one such handle makes the
/// next legitimate client fail `win32=231 ERROR_PIPE_BUSY`.
///
/// `NR` closes it, and that is no longer a supposition: the elevation work
/// labels its elevated endpoint `NWNR`, and hardware verification shows the
/// `NR` denies every medium open including `GENERIC_READ` and
/// `READ_CONTROL`. It is supplied there rather than duplicated here, since
/// both would collide on the same SDDL term for no net gain once they land,
/// and changing the label here would invalidate this PR's live descriptor
/// readback.
///
/// The returned string is OS-allocated; free it with `sys.LocalFree`.
fn allocIpcPipeIntegritySid(token: windows.HANDLE) ![*:0]u16 {
    var label_buf: [256]u8 align(@alignOf(sys.TOKEN_MANDATORY_LABEL)) = undefined;
    var label_len: u32 = 0;
    if (sys.GetTokenInformation(
        token,
        c.TokenIntegrityLevel,
        &label_buf,
        label_buf.len,
        &label_len,
    ) == 0) return error.IpcSecurityDescriptorFailed;
    const label: *const sys.TOKEN_MANDATORY_LABEL = @ptrCast(&label_buf);

    var sid_string: ?[*:0]u16 = null;
    if (sys.ConvertSidToStringSidW(
        label.Label.Sid,
        &sid_string,
    ) == 0) return error.IpcSecurityDescriptorFailed;
    const sid = sid_string orelse return error.IpcSecurityDescriptorFailed;

    _ = integrityRidFromSidString(std.mem.span(sid)) orelse {
        _ = sys.LocalFree(@ptrCast(sid));
        return error.IpcSecurityDescriptorFailed;
    };
    return sid;
}

/// Build the security descriptor for the single-instance IPC pipe: a
/// protected DACL whose only ACE grants full access to the SID that owns
/// this process, plus an explicit mandatory-label ACE at the process's exact
/// integrity level. Without it the pipe gets the default DACL, which is wider
/// than the same-user contract the IPC verbs assume.
///
/// The current user's SID is resolved from the process token rather than
/// using the `OW` (owner rights) SDDL alias, because an elevated token's
/// default object owner is the Administrators group, not the user.
///
/// Returns a descriptor allocated by the OS; free it with `sys.LocalFree`.
fn allocIpcPipeSecurityDescriptor() !*anyopaque {
    var token: windows.HANDLE = undefined;
    if (sys.OpenProcessToken(
        windows.kernel32.GetCurrentProcess(),
        c.TOKEN_QUERY,
        &token,
    ) == 0) return error.IpcSecurityDescriptorFailed;
    defer _ = windows.CloseHandle(token);

    // A TOKEN_USER plus the largest well-formed SID fits comfortably here;
    // SECURITY_MAX_SID_SIZE is 68 bytes.
    var token_user_buf: [256]u8 align(@alignOf(sys.TOKEN_USER)) = undefined;
    var token_user_len: u32 = 0;
    if (sys.GetTokenInformation(
        token,
        c.TokenUser,
        &token_user_buf,
        token_user_buf.len,
        &token_user_len,
    ) == 0) return error.IpcSecurityDescriptorFailed;
    const token_user: *const sys.TOKEN_USER = @ptrCast(&token_user_buf);

    var sid_string: ?[*:0]u16 = null;
    if (sys.ConvertSidToStringSidW(
        token_user.User.Sid,
        &sid_string,
    ) == 0) return error.IpcSecurityDescriptorFailed;
    const sid = sid_string orelse return error.IpcSecurityDescriptorFailed;
    defer _ = sys.LocalFree(@ptrCast(sid));

    const integrity_sid = try allocIpcPipeIntegritySid(token);
    defer _ = sys.LocalFree(@ptrCast(integrity_sid));

    // Pin the owner to the token user as well as granting that SID access.
    // The client authenticates the owner and mandatory label directly from
    // the connected pipe object, avoiding a recyclable process-ID lookup.
    var sddl_buf: [320]u16 = undefined;
    const sddl = try buildIpcPipeSddl(
        &sddl_buf,
        std.mem.span(sid),
        std.mem.span(integrity_sid),
    );

    var descriptor: ?*anyopaque = null;
    if (sys.ConvertStringSecurityDescriptorToSecurityDescriptorW(
        sddl.ptr,
        c.SDDL_REVISION_1,
        &descriptor,
        null,
    ) == 0) return error.IpcSecurityDescriptorFailed;

    return descriptor orelse error.IpcSecurityDescriptorFailed;
}

fn ipcServerMain(app: *App) void {
    const pipe_name = app.ipc_pipe_name orelse return;

    // Fail closed: with the default named-pipe security descriptor the pipe
    // grants Administrators and LocalSystem full control, grants Everyone
    // read (enough to occupy instances and observe the channel), and is
    // reachable over SMB. Refuse to listen at all if the descriptor cannot
    // be built rather than falling back to that.
    const descriptor = allocIpcPipeSecurityDescriptor() catch |err| {
        log.warn("failed to build win32 IPC pipe security descriptor err={}", .{err});
        return;
    };
    defer _ = sys.LocalFree(descriptor);

    var security_attributes: windows.SECURITY_ATTRIBUTES = .{
        .nLength = @sizeOf(windows.SECURITY_ATTRIBUTES),
        .lpSecurityDescriptor = descriptor,
        .bInheritHandle = windows.FALSE,
    };

    server: while (!app.ipc_stop_requested.load(.acquire)) {
        const pipe = sys.CreateNamedPipeW(
            pipe_name.ptr,
            c.PIPE_ACCESS_DUPLEX,
            windows.PIPE_TYPE_BYTE |
                c.PIPE_READMODE_BYTE |
                win32_ipc.pipe_nowait |
                c.PIPE_REJECT_REMOTE_CLIENTS,
            c.PIPE_UNLIMITED_INSTANCES,
            16 * 1024,
            16 * 1024,
            0,
            &security_attributes,
        );
        if (pipe == windows.INVALID_HANDLE_VALUE) {
            log.warn("failed to create win32 IPC pipe err={}", .{
                windows.kernel32.GetLastError(),
            });
            return;
        }

        connect: while (!app.ipc_stop_requested.load(.acquire)) {
            const connected = sys.ConnectNamedPipe(pipe, null);
            if (connected != 0) break :connect;
            const err = windows.kernel32.GetLastError();
            switch (err) {
                .PIPE_CONNECTED => break :connect,
                .PIPE_LISTENING, .NO_DATA => {
                    std.Thread.sleep(ipc_poll_interval_ns);
                    continue;
                },
                else => {
                    _ = windows.CloseHandle(pipe);
                    if (!app.ipc_stop_requested.load(.acquire)) {
                        log.warn("failed to connect win32 IPC client err={}", .{err});
                    }
                    continue :server;
                },
            }
        }

        if (app.ipc_stop_requested.load(.acquire)) {
            _ = windows.CloseHandle(pipe);
            break;
        }

        _ = handleIpcClient(app, pipe) catch |err| {
            log.warn("failed to process win32 IPC client err={}", .{err});
            _ = windows.CloseHandle(pipe);
            continue :server;
        };
        // Each pipe instance serves one request. Closing only the server handle
        // keeps unread response bytes available through the client's handle;
        // DisconnectNamedPipe would discard them.
        _ = windows.CloseHandle(pipe);
    }
}

fn handleIpcClient(app: *App, pipe: windows.HANDLE) !win32_ipc.RequestKind {
    const kind = win32_ipc.decodeRequestKind(pipe) catch |err| {
        win32_ipc.writeAck(pipe, false) catch {};
        return err;
    };

    switch (kind) {
        .new_window => handleNewWindowIpcClient(app, pipe) catch |err| {
            log.warn("failed to process win32 new-window IPC request err={}", .{err});
            try win32_ipc.writeAck(pipe, false);
        },
        .list_windows => handleListWindowsIpcClient(app, pipe) catch |err| {
            log.warn("failed to process win32 automation list IPC request err={}", .{err});
            try win32_ipc.writeDataResponse(pipe, false, "");
        },
        .perform_action => handlePerformActionIpcClient(app, pipe) catch |err| {
            log.warn("failed to process win32 automation action IPC request err={}", .{err});
            try win32_ipc.writeAck(pipe, false);
        },
        .launch_layout => handleLaunchLayoutIpcClient(app, pipe) catch |err| {
            log.warn("failed to process win32 launch-layout IPC request err={}", .{err});
            try win32_ipc.writeAck(pipe, false);
        },
    }
    return kind;
}

fn handleNewWindowIpcClient(app: *App, pipe: windows.HANDLE) !void {
    const arguments = try win32_ipc.decodeNewWindowPayload(app.core_app.alloc, pipe);
    errdefer win32_ipc.freeOwnedArguments(app.core_app.alloc, arguments);

    // Reject policy-invalid requests before the success ACK. The UI-thread
    // path repeats the same checks as defense in depth, but acknowledging
    // here first would make +new-window exit successfully without creating a
    // window.
    if (!newWindowIpcArgumentsAccepted(arguments)) {
        try win32_ipc.writeAck(pipe, false);
        win32_ipc.freeOwnedArguments(app.core_app.alloc, arguments);
        return;
    }

    const mailbox: CoreApp.Mailbox = .{
        .rt_app = app,
        .mailbox = &app.core_app.mailbox,
    };
    if (mailbox.push(.{ .new_window = .{
        .arguments = arguments,
    } }, .{ .ns = win32_ipc.io_timeout_ms * std.time.ns_per_ms }) == 0) {
        return error.IPCFailed;
    }

    try win32_ipc.writeAck(pipe, true);
}

fn newWindowIpcArgumentsAccepted(arguments: ?[]const [:0]const u8) bool {
    const argv = arguments orelse return true;
    return switch (scanForwardedToastActivation(argv)) {
        .activation => true,
        .malformed => false,
        .none => forwardedArgvRejection(argv) == null,
    };
}

fn handleListWindowsIpcClient(app: *App, pipe: windows.HANDLE) !void {
    const json = try requestAutomationWindowListJson(app, app.core_app.alloc);
    defer app.core_app.alloc.free(json);
    try win32_ipc.writeDataResponse(pipe, true, json);
}

fn handlePerformActionIpcClient(app: *App, pipe: windows.HANDLE) !void {
    const payload = win32_ipc.decodePerformActionPayload(app.core_app.alloc, pipe) catch |err| switch (err) {
        error.InvalidAutomationAction => {
            try win32_ipc.writeAckStatus(pipe, win32_ipc.ack_invalid_automation_action);
            return;
        },
        else => return err,
    };
    defer app.core_app.alloc.free(payload.action_text);

    requestAutomationAction(app, payload.target, payload.action_text) catch |err| {
        const status: u8 = switch (err) {
            error.InvalidAutomationAction => win32_ipc.ack_invalid_automation_action,
            error.UnsafeAutomationAction => win32_ipc.ack_unsafe_automation_action,
            error.InvalidAutomationTarget => win32_ipc.ack_invalid_automation_target,
            error.NoAutomationTarget => win32_ipc.ack_no_automation_target,
            else => return err,
        };
        try win32_ipc.writeAckStatus(pipe, status);
        return;
    };
    try win32_ipc.writeAck(pipe, true);
}

fn handleLaunchLayoutIpcClient(app: *App, pipe: windows.HANDLE) !void {
    const name = win32_ipc.decodeLaunchLayoutPayload(app.core_app.alloc, pipe) catch |err| {
        log.warn("invalid win32 launch-layout IPC request err={}", .{err});
        try win32_ipc.writeAckStatus(pipe, win32_ipc.ack_invalid_automation_action);
        return;
    };
    defer app.core_app.alloc.free(name);

    // Name validation restricts this to an unambiguous action payload.
    const action_text = try std.fmt.allocPrint(
        app.core_app.alloc,
        "launch_layout:{s}",
        .{name},
    );
    defer app.core_app.alloc.free(action_text);

    requestAutomationAction(app, .focused, action_text) catch |err| {
        const status: u8 = switch (err) {
            error.InvalidAutomationAction => win32_ipc.ack_invalid_automation_action,
            error.UnsafeAutomationAction => win32_ipc.ack_unsafe_automation_action,
            error.InvalidAutomationTarget => win32_ipc.ack_invalid_automation_target,
            error.NoAutomationTarget => win32_ipc.ack_no_automation_target,
            else => return err,
        };
        try win32_ipc.writeAckStatus(pipe, status);
        return;
    };
    try win32_ipc.writeAck(pipe, true);
}

fn requestAutomationWindowListJson(app: *App, alloc: Allocator) ![]u8 {
    const request = try CoreApp.Message.AutomationWindowListRequest.create(alloc);
    defer request.release();
    request.retain(); // Mailbox-consumer ownership.
    const mailbox: CoreApp.Mailbox = .{
        .rt_app = app,
        .mailbox = &app.core_app.mailbox,
    };
    if (mailbox.push(.{ .automation_window_list = request }, .{ .ns = win32_ipc.io_timeout_ms * std.time.ns_per_ms }) == 0) {
        request.release();
        return error.IPCFailed;
    }

    try waitForAutomationCompletion(app, &request.completed);
    if (request.err) |err| return err;
    return request.takeResult() orelse error.IPCFailed;
}

fn requestAutomationAction(
    app: *App,
    target: apprt.ipc.AutomationActionTarget,
    action_text: []const u8,
) !void {
    if (action_text.len == 0 or action_text.len > win32_ipc.max_action_text_len) {
        return error.InvalidAutomationAction;
    }

    const request = try CoreApp.Message.AutomationActionRequest.create(
        app.core_app.alloc,
        target,
        action_text,
    );
    defer request.release();
    request.retain(); // Mailbox-consumer ownership.
    const mailbox: CoreApp.Mailbox = .{
        .rt_app = app,
        .mailbox = &app.core_app.mailbox,
    };
    if (mailbox.push(.{ .automation_action = request }, .{ .ns = win32_ipc.io_timeout_ms * std.time.ns_per_ms }) == 0) {
        request.release();
        return error.IPCFailed;
    }

    try waitForAutomationCompletion(app, &request.completed);
    if (request.err) |err| return err;
}

fn waitForAutomationCompletion(app: *const App, completed: *const std.atomic.Value(bool)) !void {
    const deadline_ms = sys.GetTickCount64() +| win32_ipc.automation_response_timeout_ms;
    while (!completed.load(.acquire)) {
        if (app.ipc_stop_requested.load(.acquire)) return error.IPCFailed;
        if (sys.GetTickCount64() >= deadline_ms) return error.IpcTimeout;
        std.Thread.sleep(std.time.ns_per_ms);
    }
}

pub fn getProcAddress(name: [*:0]const u8) callconv(.c) ?*const anyopaque {
    if (sys.wglGetProcAddress(name)) |ptr| {
        const raw = @intFromPtr(ptr);
        if (raw > 3 and raw != std.math.maxInt(usize)) return ptr;
    }

    if (gl_startup.opengl32_module == null) {
        gl_startup.opengl32_module = sys.LoadLibraryA(opengl32_name);
        if (gl_startup.opengl32_module == null) {
            recordOpenGLStartupWin32Failure(.load_opengl32, windows.kernel32.GetLastError());
        }
    }

    const module = gl_startup.opengl32_module orelse return null;
    return sys.GetProcAddress(module, name);
}

const UpdateNotice = struct {
    version_text: ?[]u8 = null,
    release_url: ?[]u8 = null,
    message_text: ?[]u8 = null,
    staged: bool = false,

    fn init(alloc: Allocator, version_text: []const u8, release_url: []const u8, staged: bool) !UpdateNotice {
        return .{
            .version_text = try alloc.dupe(u8, version_text),
            .release_url = try alloc.dupe(u8, release_url),
            .message_text = if (staged)
                try std.fmt.allocPrint(
                    alloc,
                    "Update downloaded and verified: noctty {s} is ready to install.",
                    .{version_text},
                )
            else
                try std.fmt.allocPrint(
                    alloc,
                    "Update available: noctty {s} is ready on GitHub Releases.",
                    .{version_text},
                ),
            .staged = staged,
        };
    }

    fn deinit(self: *UpdateNotice, alloc: Allocator) void {
        if (self.version_text) |value| alloc.free(value);
        if (self.release_url) |value| alloc.free(value);
        if (self.message_text) |value| alloc.free(value);
        self.* = undefined;
    }
};

const UpdateCheckRequest = struct {
    alloc: Allocator,
    ui_thread_id: DWORD,
    state_path: []u8,
    current_version: std.SemanticVersion,
    current_version_string: []u8,
    force: bool,
    manual: bool,
    respect_dismissal: bool,
    download: bool,

    fn deinit(self: *UpdateCheckRequest) void {
        self.alloc.free(self.state_path);
        self.alloc.free(self.current_version_string);
        self.* = undefined;
    }
};

const UpdateCheckCompletion = struct {
    alloc: Allocator,
    release: ?updatepkg.Release = null,
    manual_message: ?[]u8 = null,
    staged: bool = false,

    fn deinit(self: *UpdateCheckCompletion) void {
        if (self.release) |*value| value.deinit(self.alloc);
        if (self.manual_message) |value| self.alloc.free(value);
        self.* = undefined;
    }
};

const RecoveryStartup = struct {
    attempts: [win32_recovery.max_attempts]win32_recovery.StartupAttempt = undefined,
    count: usize = 0,
    decision: win32_recovery.Decision = .normal,
};

fn unixMillis() u64 {
    return @intCast(@max(std.time.milliTimestamp(), 0));
}

fn utf8PrefixLen(value: []const u8, capacity: usize) usize {
    var len = @min(value.len, capacity);
    while (len > 0 and !std.unicode.utf8ValidateSlice(value[0..len])) {
        len -= 1;
    }
    return len;
}

fn settingsFileSize(size: u64) win32_settings.SaveError!usize {
    const max_config_size = 16 * 1024 * 1024;
    if (size > max_config_size) return error.SerializeFailed;
    return @intCast(size);
}

const SettingsConfigKey = @import("../config/key.zig").Key;
const SettingsEditedKeySet = std.StaticBitSet(std.enums.values(SettingsConfigKey).len);
const settings_explicit_optional_edit_keys = .{
    SettingsConfigKey.theme,
    SettingsConfigKey.command,
    SettingsConfigKey.@"auto-update",
    SettingsConfigKey.@"auto-update-channel",
};

fn settingsUserEditedKeys(
    original: *const configpkg.Config,
    pending: *const configpkg.Config,
) SettingsEditedKeySet {
    var edited: SettingsEditedKeySet = .initEmpty();
    inline for (@typeInfo(configpkg.Config).@"struct".fields) |field| {
        if (field.name[0] == '_') continue;
        switch (@typeInfo(field.type)) {
            .bool, .int, .float, .@"enum", .@"struct", .@"union" => {
                const key = @field(SettingsConfigKey, field.name);
                if (original.changed(pending, key)) edited.set(@intFromEnum(key));
            },
            else => {},
        }
    }
    inline for (settings_explicit_optional_edit_keys) |key| {
        if (original.changed(pending, key)) edited.set(@intFromEnum(key));
    }
    return edited;
}

fn settingsEditedValueMasked(
    pending: *const configpkg.Config,
    reloaded: *const configpkg.Config,
    comptime key: SettingsConfigKey,
) bool {
    if (key == SettingsConfigKey.@"auto-update-channel") {
        const expected = pending.@"auto-update-channel" orelse build_config.release_channel;
        const actual = reloaded.@"auto-update-channel" orelse build_config.release_channel;
        return expected != actual;
    }
    return pending.changed(reloaded, comptime key);
}

test "win32 bounded UTF-8 prefix never splits a codepoint" {
    const value = "123\u{1f680}tail";
    try std.testing.expectEqual(@as(usize, 3), utf8PrefixLen(value, 4));
    try std.testing.expectEqual(@as(usize, 7), utf8PrefixLen(value, 7));
    try std.testing.expectEqual(value.len, utf8PrefixLen(value, value.len + 10));
}

test "win32 settings save rejects files above the read cap" {
    try std.testing.expectEqual(@as(usize, 16 * 1024 * 1024), try settingsFileSize(16 * 1024 * 1024));
    try std.testing.expectError(error.SerializeFailed, settingsFileSize(16 * 1024 * 1024 + 1));
}

fn localAppDataPathAlloc(alloc: Allocator, name: []const u8) ?[]u8 {
    const local = std.process.getEnvVarOwned(alloc, "LOCALAPPDATA") catch return null;
    defer alloc.free(local);
    const dir = std.fs.path.join(alloc, &.{ local, "noctty" }) catch return null;
    defer alloc.free(dir);
    return std.fs.path.join(alloc, &.{ dir, name }) catch null;
}

fn beginRecoveryStartup(alloc: Allocator) RecoveryStartup {
    var result: RecoveryStartup = .{};
    const now = unixMillis();
    var record: win32_recovery.StartupAttemptRecord = .{};
    var parsed_record: ?std.json.Parsed(win32_recovery.StartupAttemptRecord) = null;
    defer if (parsed_record) |*parsed| parsed.deinit();

    if (localAppDataPathAlloc(alloc, "startup-attempts.json")) |path| {
        defer alloc.free(path);
        if (std.fs.openFileAbsolute(path, .{})) |file| {
            defer file.close();
            if (file.readToEndAlloc(alloc, 64 * 1024)) |raw| {
                defer alloc.free(raw);
                parsed_record = win32_recovery.parseAlloc(alloc, raw) catch |err| invalid: {
                    log.warn("win32 recovery: ignored invalid startup history err={}", .{err});
                    break :invalid null;
                };
                if (parsed_record) |*parsed| record = parsed.value;
            } else |err| {
                log.warn("win32 recovery: startup history read failed err={}", .{err});
            }
        } else |err| switch (err) {
            error.FileNotFound => {},
            else => log.warn("win32 recovery: startup history open failed err={}", .{err}),
        }
    }

    result.decision = win32_recovery.decide(record, now, false, .{});
    const appended = win32_recovery.appendBounded(
        record,
        .{ .started_at_unix_ms = now },
        &result.attempts,
    ) catch |err| {
        log.warn("win32 recovery: attempt append failed err={}", .{err});
        return result;
    };
    result.count = appended.attempts.len;
    persistRecoveryRecord(alloc, result.attempts[0..result.count]) catch |err| {
        log.warn("win32 recovery: startup marker persist failed err={}", .{err});
    };
    return result;
}

fn persistRecoveryRecord(
    alloc: Allocator,
    attempts: []const win32_recovery.StartupAttempt,
) !void {
    const path = localAppDataPathAlloc(alloc, "startup-attempts.json") orelse return;
    defer alloc.free(path);
    const encoded = try win32_recovery.encodeAlloc(alloc, .{ .attempts = attempts });
    defer alloc.free(encoded);
    try writePersistentFileAlloc(alloc, path, encoded);
}

fn writePersistentFileAlloc(alloc: Allocator, path: []const u8, data: []const u8) !void {
    if (std.fs.path.dirname(path)) |dir| {
        // Recursive: `layouts\` sits one level below `%LOCALAPPDATA%\noctty`,
        // which itself may not exist yet on a first save.
        std.fs.cwd().makePath(dir) catch |err| switch (err) {
            error.PathAlreadyExists => {},
            else => return err,
        };
    }
    const temporary_path = try std.fmt.allocPrint(
        alloc,
        "{s}.tmp-{x}-{x}",
        .{ path, sys.GetCurrentProcessId(), unixMillis() },
    );
    defer alloc.free(temporary_path);
    try win32_session_persistence.writeFileAtomic(path, temporary_path, data);
}

fn sessionStatePolicyAllows(safe_mode: bool, policy: configpkg.Config.WindowSaveState) bool {
    return !safe_mode and policy != .never;
}

fn layoutActionResult(success: bool) !bool {
    if (!success) return error.LayoutActionFailed;
    return true;
}

const SessionRestoreTransaction = struct {
    app: ?*App = null,
    host: ?*Host = null,
    core_first: *bool,
    core_first_before: bool,
    committed: bool = false,

    fn init(app: *App) SessionRestoreTransaction {
        return .{
            .core_first = &app.core_app.first,
            .core_first_before = app.core_app.first,
        };
    }

    fn noteSurface(self: *SessionRestoreTransaction, surface: *Surface) void {
        if (self.host == null) {
            self.app = surface.app;
            self.host = surface.host;
        }
    }

    fn commit(self: *SessionRestoreTransaction) void {
        self.committed = true;
    }

    fn rollback(self: *SessionRestoreTransaction) void {
        if (self.committed) return;
        if (self.app) |app| if (self.host) |host| {
            app.rollbackSessionRestoreHost(host);
            // A failed DestroyWindow deliberately retains the partial host.
            // Do not make that live surface look like a fresh first surface.
            if (std.mem.indexOfScalar(*Host, app.hosts.items, host) != null) return;
        };
        self.core_first.* = self.core_first_before;
    }
};

fn sessionRestorePolicyAllows(
    safe_mode: bool,
    policy: configpkg.Config.WindowSaveState,
    initial_window: bool,
    has_initial_command: bool,
    startup_profile_picker: bool,
) bool {
    return sessionStatePolicyAllows(safe_mode, policy) and
        initial_window and
        !has_initial_command and
        !startup_profile_picker;
}

pub const App = struct {
    pub const must_draw_from_app_thread = true;

    core_app: *CoreApp,
    config: configpkg.Config,
    config_revision: u64 = 1,
    resolved_theme: ThemeColors = darkTheme(),
    hinstance: HINSTANCE,
    class_atom: ATOM = 0,
    host_class_atom: ATOM = 0,
    palette_list_class_atom: ATOM = 0,
    scrollbar_class_atom: ATOM = 0,
    hosts: std.ArrayListUnmanaged(*Host) = .empty,
    windows: std.ArrayListUnmanaged(*Surface) = .empty,
    /// Internal test seam so action-path tests can drive real
    /// `performAction(.new_tab, ...)` logic without requiring HWND/GL
    /// surface bring-up.
    test_create_window_surface: ?*const fn (
        app: *App,
        config: *const configpkg.Config,
        title: LPCWSTR,
        opts: SurfaceInitOptions,
    ) anyerror!*Surface = null,
    /// Test-only interleaving seam for the focus revision race between a
    /// structural split-close prepare and commit.
    test_before_split_undo_shell_commit: ?*const fn (
        app: *App,
        source_pane: win32_shell.model.PaneId,
    ) anyerror!void = null,
    next_host_id: u32 = 1,
    launcher_profile_key: ?[:0]const u8 = null,
    launcher_profile_hint: ?[:0]const u8 = null,
    launcher_profile_order_hint: ?[:0]const u8 = null,
    launcher_quick_slot_keys: [3]?[:0]const u8 = .{ null, null, null },
    launcher_profile_target: ProfileOpenTarget = .tab,
    startup_profile_picker: bool = false,
    wheel_settings: SystemWheelSettings = .{},
    system_dynamic_scrollbars: bool = true,
    ipc_pipe_name: ?[:0]const u16 = null,
    ipc_thread: ?std.Thread = null,
    ipc_stop_requested: std.atomic.Value(bool) = .init(false),
    global_hotkeys: std.ArrayListUnmanaged(RegisteredGlobalHotkey) = .empty,
    global_hotkeys_dirty: bool = false,
    ui_thread_id: DWORD = 0,
    quit_timer_id: ?UINT_PTR = null,
    undo_prune_timer_id: ?UINT_PTR = null,
    next_undo_sequence: u64 = 1,
    running: bool = false,
    /// A normal last-host close destroys the native/session model before
    /// `terminate` runs. Preserve the successful pre-close snapshot instead
    /// of replacing it with an empty snapshot during final teardown.
    session_state_saved_before_last_host_close: bool = false,
    /// True only while the app is synchronously draining every host during
    /// shutdown. Child HWND teardown still repairs native split trees, but it
    /// must not diagnose the intentionally absent per-pane close preflight as
    /// an ordinary-close invariant failure.
    quitting: bool = false,
    /// Host currently undergoing allocation-free failed-restore teardown.
    /// Its child WM_DESTROY callbacks remove Surface ownership only; Host
    /// tree disposal happens once, after the native cascade completes.
    session_restore_rollback_host: ?*Host = null,
    windows_hidden: bool = false,
    quick_terminal_keyboard_diagnostic_logged: bool = false,
    update_check_running: std.atomic.Value(bool) = .init(false),
    update_notice: ?UpdateNotice = null,
    update_auto_check_started: bool = false,
    /// Most-recently-used command palette actions; newest first. Strings
    /// are owned by `core_app.alloc` and freed in `App.deinit`. Surfaced
    /// by `commandPaletteBannerText` when the query is empty so users
    /// see their own recent picks instead of the static onboarding hint.
    palette_mru: [5]?[:0]const u8 = .{null} ** 5,
    /// Singleton settings window. Lazily created by the `open_config`
    /// action; `App.terminate` destroys the HWND if still alive.
    settings_window: win32_settings.SettingsWindow = undefined,
    /// Stable core surface id that owned focus when Settings opened. Settings
    /// itself clears terminal focus flags, so close must not guess host zero.
    settings_restore_surface_id: ?u64 = null,
    /// Whether `CoInitializeEx` actually took responsibility for the
    /// apartment on this thread. `CoUninitialize` only pairs with a
    /// successful init (`S_OK` / `S_FALSE`) — `RPC_E_CHANGED_MODE`
    /// means another component already set up COM and we must not
    /// touch it on the way down.
    com_initialized: bool = false,
    /// Kernel build number from `RtlGetVersion`. 0 if probe failed.
    /// 22000 = Win11 21H2; 22621 = Win11 22H2
    /// (`DWMWA_SYSTEMBACKDROP_TYPE` / `DWMSBT_TABBEDWINDOW`).
    /// Future chrome gates read this directly; no runtime config flag,
    /// per §12 Q1.
    os_build: u32 = 0,
    /// Top-level switch for the integrated-titlebar path
    /// (`WM_NCCALCSIZE` / `WM_NCHITTEST` state machine). Derived
    /// from the Win11 build floor via `shouldUseIntegratedTitlebar`;
    /// false keeps the stock non-client caption path.
    use_integrated_titlebar: bool = false,
    // Live-resize state is tracked PER HOST (`Host.is_live_resize`),
    // not per App. Dragging window A must NOT freeze renderer
    // invalidations for unrelated background windows B/C.
    /// Cached CF_HTML clipboard format ID — lazy-registered on
    /// first HTML copy. Process-local so one cache per App is
    /// enough; re-registering on every copy is documented as
    /// cheap by MS but still pointless work.
    cf_html_format: UINT = 0,
    /// Hyperlink hover-dwell tracker. Reset via `dismiss()` whenever
    /// focus leaves a surface or a click arrives.
    link_hover_tracker: win32_link_preview.HoverTracker = undefined,
    /// Windows Action Center toast notifier. `null` when WinRT init
    /// fails (e.g. corporate lockdown, missing combase.dll), in which
    /// case `showDesktopNotification` falls back to the in-app banner
    /// path. One notifier per App, released in `App.terminate`.
    winrt_toast: ?win32_toast_winrt.WinrtToast = null,
    /// Taskbar progress COM object. `null` when the taskbar API is
    /// unavailable, in which case progress continues to render only in
    /// the window title/status text.
    taskbar_progress: ?win32_taskbar_progress.TaskbarProgress = null,
    toast_activation_post_pending: std.atomic.Value(bool) = .init(false),
    /// Absolute path supplied via `--config-file <path>` on the CLI.
    /// Resolved ONCE against the startup cwd during `App.init` — that's
    /// important because `run()` later calls `sanitizeCurrentDirectory()`,
    /// which can reset cwd to `%USERPROFILE%`. If we resolved the
    /// relative path at save time, we'd end up writing to a different
    /// file than the one `Config.load()` used at launch.
    cli_config_override_path: ?[]u8 = null,
    /// Startup-time cwd snapshot. `Config.load()` resolves relative
    /// `--config-file` argv entries via realpath-against-cwd, so any
    /// reload that happens after `sanitizeCurrentDirectory()` would
    /// resolve those entries against the sanitized cwd and end up
    /// reading a different file than launch did. We `std.fs.cwd()`
    /// chdir back to this value around `settingsSaveAndReload`'s
    /// reload so argv-relative paths re-resolve identically.
    startup_cwd: ?[]u8 = null,
    /// Parsed `wgh://activate?...` launch argument from a cold-start
    /// toast activation. `null` when no such argv entry is present.
    /// Consumed once after the first window spawns. We first try the
    /// requested surface/window identity and fall back to the newly
    /// created primary surface when the IDs came from a prior process.
    pending_toast_activation: ?win32_toast_activation.ActivationTarget = null,
    /// Ephemeral recovery launch: default config, no saved workspace restore.
    safe_mode: bool = false,
    recovery_startup: RecoveryStartup = .{},
    /// Top-level shell composition only. Terminal child HWNDs retain their
    /// existing WGL/SwapBuffers ownership regardless of this backend state.
    shell_compositor_driver: win32_compositor_native.NativeDriver = undefined,
    shell_compositor: win32_compositor.Backend = undefined,
    shell_compositor_initialized: bool = false,
    shell_runtime: win32_shell.runtime.Runtime = undefined,
    shell_runtime_initialized: bool = false,

    pub fn init(
        self: *App,
        core_app: *CoreApp,
        opts: struct { safe_mode: bool = false },
    ) !void {
        const recovery_startup = beginRecoveryStartup(core_app.alloc);
        const safe_mode = opts.safe_mode or recovery_startup.decision == .safe_mode;
        self.* = .{
            .core_app = core_app,
            .config = if (safe_mode) config: {
                var config = try configpkg.Config.default(core_app.alloc);
                errdefer config.deinit();
                try config.finalize();
                break :config config;
            } else try configpkg.Config.load(core_app.alloc),
            .safe_mode = safe_mode,
            .recovery_startup = recovery_startup,
            .hinstance = sys.GetModuleHandleW(null),
            .launcher_profile_hint = detectDefaultProfileHint(core_app.alloc),
            .launcher_profile_order_hint = windows_shell.profileOrderHint(core_app.alloc),
            .launcher_profile_target = detectDefaultProfileTarget(core_app.alloc),
            .startup_profile_picker = detectStartupProfilePicker(core_app.alloc),
        };
        // Install before any host window exists, so the very first
        // SetWinEventHook registration already has somewhere to deliver.
        cloak_event_app = self;
        win32_power.setCloakEventHandler(&onHostCloakEvent);
        // Snapshot the CLI --config-file override BEFORE any code has
        // a chance to chdir. See the field comment above.
        self.cli_config_override_path = cliConfigFileOverride(core_app.alloc) catch null;
        // Snapshot the startup cwd for reload-time restoration.
        self.startup_cwd = std.process.getCwdAlloc(core_app.alloc) catch null;
        // Scan argv for a cold-start toast activation arg. Silent on
        // absence or malformed input — activation is opt-in.
        self.pending_toast_activation = scanToastActivationArg(core_app.alloc);
        if (self.pending_toast_activation) |target| {
            log.info("toast activation received surface={?} tab={?} window={?} action={?}", .{
                target.surface_id,
                target.tab_id,
                target.window_id,
                target.action,
            });
        }
        // AUMID registration MUST precede any HWND creation so
        // taskbar-grouping / toast attribution picks up our identity
        // on the first window. Both calls swallow failures (warn +
        // continue) — toasts and taskbar grouping are non-essential
        // for basic terminal function.
        win32_aumid.setProcessAumid();
        win32_aumid.registerAumidDisplayName(core_app.alloc);

        // Boot the WinRT toast notifier. Failure falls back to the
        // host banner/log path in `showDesktopNotificationWithLaunch`.
        // MUST run AFTER `setProcessAumid` so `CreateToastNotifierWithId`
        // attributes toasts to our AUMID.
        const aumid_utf16 = std.unicode.utf8ToUtf16LeStringLiteral("io.github.amanthanvi.noctty");
        self.winrt_toast = win32_toast_winrt.WinrtToast.init(core_app.alloc, aumid_utf16) catch |err| blk: {
            std.log.warn("winrt toast init failed err={}; falling back to host notifications", .{err});
            break :blk null;
        };
        if (self.winrt_toast) |*toast| {
            toast.setActivationCallback(self, winrtToastActivationCallback);
        }

        // Install the PowerShell shell-integration script into
        // %LOCALAPPDATA%\noctty\shell-integration\powershell\
        // if missing or the on-disk hash doesn't match the embedded
        // payload (forces updates when we ship a new version). This
        // keeps the manual `$PROFILE` fallback on a stable path even
        // though automatic injection now uses the resources-tree copy
        // for interactive PowerShell launches.
        if (win32_powershell_install.resolveInstallPath(core_app.alloc)) |ps1_path| {
            defer core_app.alloc.free(ps1_path);
            const result = win32_powershell_install.installIfStale(core_app.alloc, ps1_path);
            log.info("powershell integration install path={s} result={s}", .{ ps1_path, @tagName(result) });
        } else |err| {
            std.log.warn("powershell integration install path resolve failed err={}", .{err});
        }

        // Windows version probe. Win11 build 22000+ enables the
        // integrated-titlebar path; older builds stay on the stock
        // non-client caption/buttons path.
        self.os_build = probeWindowsBuild();
        self.use_integrated_titlebar = shouldUseIntegratedTitlebar(
            self.os_build,
            self.config.@"window-show-tab-bar",
        );
        log.info("win32 os_build={d} integrated_titlebar={}", .{
            self.os_build,
            self.use_integrated_titlebar,
        });
        if (recovery_startup.decision == .safe_mode and !opts.safe_mode) {
            log.warn("win32 recovery: repeated incomplete startups selected safe mode", .{});
        }

        self.initComApartment();
        self.taskbar_progress = win32_taskbar_progress.TaskbarProgress.init() catch |err| blk: {
            std.log.warn("taskbar progress init failed err={}; falling back to title-only progress", .{err});
            break :blk null;
        };
        self.refreshSystemWheelSettings();
        self.refreshSystemScrollbarPreference();
        self.resolved_theme = resolveTheme(&self.config);
        self.loadPaletteMru();
        self.settings_window = win32_settings.SettingsWindow.init(.{
            .ctx = @ptrCast(self),
            .alloc = core_app.alloc,
            .hinstance = self.hinstance,
            .ownerWindow = &settingsOwnerWindowThunk,
            .chromeBg = &settingsChromeBgThunk,
            .textPrimary = &settingsTextPrimaryThunk,
            .themeColors = &settingsThemeColorsThunk,
            .highContrast = &settingsHighContrastThunk,
            .openInEditor = &settingsOpenInEditorThunk,
            .currentConfig = &settingsCurrentConfigThunk,
            .saveAndReload = &settingsSaveAndReloadThunk,
            .configRevision = &settingsConfigRevisionThunk,
            .previewField = &settingsPreviewFieldThunk,
            .notifyConflict = &settingsNotifyConflictThunk,
            .notifySuccess = &settingsNotifySuccessThunk,
            .customUiaProvidersEnabled = &settingsCustomUiaProvidersEnabledThunk,
            .deferUiaDisconnect = &settingsDeferUiaDisconnectThunk,
            .onClosed = &settingsOnClosedThunk,
        });
        self.link_hover_tracker = win32_link_preview.HoverTracker.init();
        // The driver interface retains a pointer to its App-owned field, so
        // construct it only after `self.*` has established the final address.
        self.shell_compositor_driver = win32_compositor_native.NativeDriver.init(core_app.alloc);
        self.shell_compositor = win32_compositor.Backend.init(
            win32_compositor.probeNativeCapability(),
            self.shell_compositor_driver.interface(),
        );
        self.shell_compositor_initialized = true;
        self.shell_runtime = win32_shell.runtime.Runtime.init(core_app.alloc);
        self.shell_runtime_initialized = true;
        const compositor_status = self.shell_compositor.status();
        log.info("shell compositor state={s} fallback={?s}", .{
            @tagName(compositor_status.state),
            if (compositor_status.fallback_reason) |reason| @tagName(reason) else null,
        });
    }

    /// Bring the STA apartment online for in-process COM consumers
    /// (settings path picker via `IFileOpenDialog`, WinRT toast setup,
    /// OLE drag-drop). Safe to call multiple times —
    /// `S_FALSE` means "already initialised in this mode", and
    /// `RPC_E_CHANGED_MODE` means "already initialised in a different
    /// mode" and leaves STA-only consumers disabled.
    fn initComApartment(self: *App) void {
        const hr = sys.CoInitializeEx(null, c.COINIT_APARTMENTTHREADED);
        switch (hr) {
            0, 1 => self.com_initialized = true, // S_OK, S_FALSE
            c.RPC_E_CHANGED_MODE => {
                std.log.warn("COM apartment: already MTA on this thread; STA consumers may fail", .{});
            },
            else => {
                std.log.warn("COM apartment: CoInitializeEx failed hr=0x{x:0>8}", .{@as(u32, @bitCast(hr))});
            },
        }
    }

    pub fn run(self: *App) !void {
        try self.sanitizeCurrentDirectory();
        const cwd = std.process.getCwdAlloc(self.core_app.alloc) catch null;
        defer if (cwd) |v| self.core_app.alloc.free(v);
        if (cwd) |v| {
            log.debug("win32 current directory cwd={s}", .{v});
        }

        try self.ensureWindowClass();

        if (!self.safe_mode and try self.tryForwardStartupToExistingInstance()) {
            // Forwarding is a successful startup outcome for this process.
            // Mark it ready so repeated new-window launches cannot accumulate
            // false crash-loop evidence and trigger automatic safe mode.
            self.markRecoveryReady();
            return;
        }

        self.running = true;
        const ui_thread_id = sys.GetCurrentThreadId();
        @atomicStore(DWORD, &self.ui_thread_id, ui_thread_id, .release);
        ensureMessageQueue();
        defer {
            self.stopUndoPruneTimer();
            self.stopQuitTimer();
            drainDeferredUiaDisconnects(ui_thread_id);
            @atomicStore(DWORD, &self.ui_thread_id, 0, .release);
            self.running = false;
        }

        // Safe mode is an isolated recovery process. It neither forwards into
        // the normal instance nor competes for that instance's IPC endpoint.
        if (!self.safe_mode) try self.startIpcServer();

        if (self.config.@"launch-layout") |name| {
            // An explicit CLI layout request is honored even when
            // `initial-window` is disabled, because the user asked for this
            // exact window. It is also one-shot: later ordinary new-window
            // actions must not inherit and replay it from the app config.
            const launched = self.launchNamedLayout(name, null);
            self.config.@"launch-layout" = null;
            // Clearing the field is not enough: `finalize` -> `loadTheme` and
            // `changeConditionalState` replay `_replay_steps` through
            // `loadIter`, and a per-window clone inherits that history, so a
            // surviving startup step would turn a later ordinary new window
            // into a layout launch.
            _ = self.config.dropLaunchLayoutReplaySteps(0);
            if (!launched) {
                try self.createWindow(default_title);
                if (self.primarySurface()) |surface| if (surface.host) |host| {
                    host.setBanner(.err, "Layout could not be opened.") catch {};
                };
            }
        } else if (self.config.@"initial-window") {
            const restored = if (self.sessionRestoreEligible()) try self.restoreSessionState() else false;
            if (!restored) try self.createWindow(default_title);
            if (!restored and self.startup_profile_picker) {
                if (self.primarySurface()) |surface| {
                    if (surface.host) |host| _ = host.toggleProfileOverlay();
                }
            }
        } else {
            log.info("initial-window is disabled; win32 runtime waiting without a window", .{});
        }

        self.scheduleGlobalHotkeySync();
        if (self.global_hotkeys_dirty and self.windows.items.len == 0) {
            self.global_hotkeys_dirty = false;
            self.syncGlobalHotkeys() catch |err| {
                log.err("failed to sync win32 global hotkeys err={}", .{err});
            };
        }
        if (self.windows.items.len == 0) self.startQuitTimer();

        self.markRecoveryReady();

        var msg: MSG = undefined;
        while (true) {
            const result = sys.GetMessageW(&msg, null, 0, 0);
            if (result == -1) return lastError();
            if (result == 0) break;

            if (msg.message == c.WM_WINHOSTTY_WAKE) {
                if (self.global_hotkeys_dirty) {
                    self.global_hotkeys_dirty = false;
                    self.syncGlobalHotkeys() catch |err| {
                        log.err("failed to sync win32 global hotkeys err={}", .{err});
                    };
                }
                try self.core_app.tick(self);
                if (!self.running and self.windows.items.len == 0) break;
                continue;
            }

            if (msg.message == c.WM_WINHOSTTY_UPDATE) {
                const completion: *UpdateCheckCompletion = @ptrFromInt(@as(usize, @bitCast(msg.lParam)));
                defer {
                    completion.deinit();
                    self.core_app.alloc.destroy(completion);
                }
                self.handleUpdateCheckCompletion(completion);
                try self.core_app.tick(self);
                if (!self.running and self.windows.items.len == 0) break;
                continue;
            }

            if (msg.message == c.WM_WINHOSTTY_TOAST_ACTIVATION) {
                const activation: *win32_toast_activation.ActivationTarget = @ptrFromInt(@as(usize, @bitCast(msg.lParam)));
                defer std.heap.page_allocator.destroy(activation);
                defer self.toast_activation_post_pending.store(false, .release);
                if (!self.handleToastActivation(activation.*)) {
                    self.pending_toast_activation = activation.*;
                }
                try self.core_app.tick(self);
                if (!self.running and self.windows.items.len == 0) break;
                continue;
            }

            if (msg.message == c.WM_WINHOSTTY_UIA_DISCONNECT) {
                if (msg.lParam == 0) {
                    log.warn("win32 UIA deferred disconnect message had no context", .{});
                    continue;
                }
                const pending: *DeferredUiaDisconnect = @ptrFromInt(@as(usize, @bitCast(msg.lParam)));
                processDeferredUiaDisconnect(self.ui_thread_id, pending);
                continue;
            }

            if (msg.message == c.WM_TIMER) {
                if (self.quit_timer_id) |timer_id| {
                    if (msg.wParam == timer_id) {
                        self.stopQuitTimer();
                        if (self.running and !self.hasLiveUiWindows() and self.config.@"quit-after-last-window-closed") {
                            self.running = false;
                            sys.PostQuitMessage(0);
                        }
                        continue;
                    }
                }
                if (self.undo_prune_timer_id) |timer_id| {
                    if (msg.wParam == timer_id) {
                        self.stopUndoPruneTimer();
                        self.pruneUndoHistoryNow();
                        continue;
                    }
                }
            }

            if (msg.message == c.WM_HOTKEY) {
                self.handleGlobalHotkey(@intCast(msg.wParam));
                continue;
            }

            // The settings surface is a modeless native dialog. Route its
            // keyboard messages through the system dialog manager so Tab,
            // Shift+Tab, arrow-key radio navigation, and default buttons use
            // standard Win32 accessibility semantics.
            if (self.settings_window.hwnd) |settings_hwnd| {
                if (sys.IsDialogMessageW(settings_hwnd, &msg) != 0) {
                    try self.core_app.tick(self);
                    continue;
                }
            }

            _ = sys.TranslateMessage(&msg);
            _ = sys.DispatchMessageW(&msg);

            if (self.global_hotkeys_dirty) {
                self.global_hotkeys_dirty = false;
                self.syncGlobalHotkeys() catch |err| {
                    log.err("failed to sync win32 global hotkeys err={}", .{err});
                };
            }

            try self.core_app.tick(self);

            if (!self.running and self.windows.items.len == 0) break;
        }
    }

    pub fn terminate(self: *App) void {
        self.stopUndoPruneTimer();
        self.stopQuitTimer();
        self.update_check_running.store(false, .release);
        if (self.update_notice) |*notice| {
            notice.deinit(self.core_app.alloc);
            self.update_notice = null;
        }
        self.unregisterGlobalHotkeys();
        self.stopIpcServer();
        if (!self.session_state_saved_before_last_host_close or self.hosts.items.len > 0) {
            _ = self.saveSessionState();
        }
        self.destroyAllWindows();
        if (self.shell_runtime_initialized) {
            self.shell_runtime.deinit();
            self.shell_runtime_initialized = false;
        }
        if (self.shell_compositor_initialized) {
            self.shell_compositor.deinit();
            self.shell_compositor_initialized = false;
        }
        // After destroyAllWindows: every Host has released its cloak-hook
        // reference by now, so no further callback can reach a freed App.
        win32_power.setCloakEventHandler(null);
        cloak_event_app = null;
        self.hosts.deinit(self.core_app.alloc);
        self.windows.deinit(self.core_app.alloc);
        self.global_hotkeys.deinit(self.core_app.alloc);
        if (self.launcher_profile_key) |value| self.core_app.alloc.free(value);
        if (self.launcher_profile_hint) |value| self.core_app.alloc.free(value);
        if (self.launcher_profile_order_hint) |value| self.core_app.alloc.free(value);
        for (self.launcher_quick_slot_keys) |value| {
            if (value) |owned| self.core_app.alloc.free(owned);
        }
        self.savePaletteMru();
        for (&self.palette_mru) |*slot| {
            if (slot.*) |owned| self.core_app.alloc.free(owned);
            slot.* = null;
        }
        self.settings_window.deinit();
        const uia_disconnect_hr = win32_uia.disconnectAllProviders();
        if (uia_disconnect_hr != 0) {
            log.warn("win32 UIA disconnect-all failed hr=0x{x}", .{@as(u32, @bitCast(uia_disconnect_hr))});
        }
        if (self.winrt_toast) |*toast| {
            toast.deinit();
            self.winrt_toast = null;
        }
        if (self.taskbar_progress) |*taskbar| {
            taskbar.deinit();
            self.taskbar_progress = null;
        }
        if (self.cli_config_override_path) |path| {
            self.core_app.alloc.free(path);
            self.cli_config_override_path = null;
        }
        if (self.startup_cwd) |path| {
            self.core_app.alloc.free(path);
            self.startup_cwd = null;
        }
        deinitImeWindowFormsTracePath(self.core_app.alloc);
        self.config.deinit();
        if (self.com_initialized) {
            sys.CoUninitialize();
            self.com_initialized = false;
        }
    }

    /// Resolve `%LOCALAPPDATA%\noctty\<name>`. Caller frees with
    /// `core_app.alloc`. Returns null if `LOCALAPPDATA` is unreadable
    /// or allocation fails.
    fn localAppDataPath(self: *const App, name: []const u8) ?[]u8 {
        return localAppDataPathAlloc(self.core_app.alloc, name);
    }

    /// Resolve `%LOCALAPPDATA%\noctty\palette-mru.txt`. Caller frees
    /// with `core_app.alloc`.
    fn paletteMruPath(self: *const App) ?[]u8 {
        return self.localAppDataPath("palette-mru.txt");
    }

    /// Resolve `%LOCALAPPDATA%\noctty\session-state.json`. Caller
    /// frees with `core_app.alloc`.
    fn sessionStatePath(self: *const App) ?[]u8 {
        return self.localAppDataPath("session-state.json");
    }

    fn namedLayoutPath(self: *const App, name: []const u8) ![]u8 {
        const relative = try win32_layouts.relativePathAlloc(self.core_app.alloc, name);
        defer self.core_app.alloc.free(relative);
        return self.localAppDataPath(relative) orelse error.LocalAppDataUnavailable;
    }

    fn namedLayoutsDirectoryPath(self: *const App) ?[]u8 {
        return self.localAppDataPath("layouts");
    }

    fn sessionStateEnabled(self: *const App) bool {
        // Safe mode is deliberately non-destructive. It starts without
        // restoring the saved session and must not replace or delete that
        // session when the diagnostic run exits.
        return self.sessionRestoreEligible();
    }

    fn sessionRestoreEligible(self: *const App) bool {
        return sessionRestorePolicyAllows(
            self.safe_mode,
            self.config.@"window-save-state",
            self.config.@"initial-window",
            self.config.@"initial-command" != null,
            self.startup_profile_picker,
        );
    }

    /// Populate `palette_mru` from the on-disk file, one action per line
    /// (newest first). Missing file, I/O errors, and parse failures all
    /// degrade to "start empty" — the MRU is a UX nicety, not a
    /// correctness invariant.
    fn loadPaletteMru(self: *App) void {
        const path = self.paletteMruPath() orelse return;
        defer self.core_app.alloc.free(path);

        const file = std.fs.openFileAbsolute(path, .{}) catch return;
        defer file.close();

        // Cap read size at 64 KB — way more than the 5 × ~200-char
        // actions we expect, but bounded so a corrupted file can't OOM.
        const raw = file.readToEndAlloc(self.core_app.alloc, 64 * 1024) catch return;
        defer self.core_app.alloc.free(raw);

        var it = std.mem.tokenizeAny(u8, raw, "\r\n");
        var slot: usize = 0;
        while (it.next()) |line| {
            if (slot >= self.palette_mru.len) break;
            const trimmed = std.mem.trim(u8, line, " \t");
            if (trimmed.len == 0) continue;
            const duped = self.core_app.alloc.dupeZ(u8, trimmed) catch continue;
            self.palette_mru[slot] = duped;
            slot += 1;
        }
    }

    /// Write `palette_mru` to the on-disk file (newest first). Failure
    /// is silently logged — losing recent history is fine, blocking
    /// termination on file-system problems is not.
    fn savePaletteMru(self: *const App) void {
        // Fast path: nothing to persist.
        if (self.palette_mru[0] == null) return;

        const path = self.paletteMruPath() orelse return;
        defer self.core_app.alloc.free(path);

        if (std.fs.path.dirname(path)) |dir| {
            std.fs.makeDirAbsolute(dir) catch |err| switch (err) {
                error.PathAlreadyExists => {},
                else => {
                    std.log.warn("palette MRU: mkdir failed path={s} err={}", .{ dir, err });
                    return;
                },
            };
        }

        const file = std.fs.createFileAbsolute(path, .{ .truncate = true }) catch |err| {
            std.log.warn("palette MRU: create failed path={s} err={}", .{ path, err });
            return;
        };
        defer file.close();

        var fbuf: [1024]u8 = undefined;
        var fw = file.writer(&fbuf);
        for (self.palette_mru) |slot| {
            if (slot) |owned| {
                fw.interface.print("{s}\n", .{owned}) catch return;
            }
        }
        fw.interface.flush() catch {};
    }

    fn loadSessionState(self: *App) !?std.json.Parsed(win32_session_state.SessionState) {
        if (!self.sessionStateEnabled()) return null;
        const path = self.sessionStatePath() orelse return null;
        defer self.core_app.alloc.free(path);

        return switch (win32_session_persistence.loadAlloc(
            self.core_app.alloc,
            path,
            win32_session_persistence.default_max_state_bytes,
        )) {
            .missing => null,
            .oversized => oversized: {
                log.warn("win32 session restore: state exceeds size limit; leaving file untouched", .{});
                break :oversized null;
            },
            .transient => |err| return err,
            .corrupt => |err| corrupt: {
                self.quarantineInvalidSessionState(path, err);
                break :corrupt null;
            },
            .loaded => |parsed| parsed,
        };
    }

    fn launchNamedLayout(self: *App, name: []const u8, preferred_banner_host: ?*Host) bool {
        const banner_host = preferred_banner_host orelse if (self.primarySurface()) |surface|
            surface.host
        else
            null;
        win32_layouts.validateName(name) catch |err| {
            log.warn("named layout launch rejected invalid name name={s} err={}", .{ name, err });
            if (banner_host) |host| host.setBanner(.err, "Invalid layout name.") catch {};
            return false;
        };
        const path = self.namedLayoutPath(name) catch |err| {
            log.warn("named layout launch path resolution failed name={s} err={}", .{ name, err });
            if (banner_host) |host| host.setBanner(.err, "Layout path is unavailable.") catch {};
            return false;
        };
        defer self.core_app.alloc.free(path);

        var loaded = win32_session_persistence.loadLayoutAlloc(
            self.core_app.alloc,
            path,
            win32_session_persistence.default_max_state_bytes,
        );
        defer loaded.deinit();
        switch (loaded) {
            .missing => {
                log.warn("named layout launch file not found name={s} path={s}", .{ name, path });
                if (banner_host) |host| host.setBanner(.err, "Layout was not found.") catch {};
                return false;
            },
            .oversized => {
                log.warn("named layout launch file exceeds size limit name={s} path={s}", .{ name, path });
                if (banner_host) |host| host.setBanner(.err, "Layout file is too large.") catch {};
                return false;
            },
            .transient => |err| {
                log.warn("named layout launch read failed name={s} path={s} err={}", .{ name, path, err });
                if (banner_host) |host| host.setBanner(.err, "Layout could not be read.") catch {};
                return false;
            },
            .corrupt => |err| {
                const quarantined = self.quarantineInvalidNamedLayout(path, name, err);
                if (banner_host) |host| host.setBanner(
                    .err,
                    if (quarantined)
                        "Invalid layout was quarantined."
                    else
                        "Invalid layout could not be quarantined.",
                ) catch {};
                return false;
            },
            .loaded => |parsed| {
                if (parsed.value.windows.len != 1) {
                    const quarantined = self.quarantineInvalidNamedLayout(
                        path,
                        name,
                        error.InvalidWindowCount,
                    );
                    if (banner_host) |host| host.setBanner(
                        .err,
                        if (quarantined)
                            "Invalid layout was quarantined."
                        else
                            "Invalid layout could not be quarantined.",
                    ) catch {};
                    return false;
                }
                // A layout file can come from a synced or shared directory, and
                // materializing one spawns a shell per pane. Refuse oversized
                // documents instead of quarantining them: the file may well be
                // the user's own, just too large for one window.
                win32_layouts.validateLaunchSize(parsed.value.windows[0]) catch |err| {
                    log.warn("named layout launch rejected oversized document name={s} err={}", .{ name, err });
                    if (banner_host) |host| host.setBanner(.err, "Layout has too many tabs or panes.") catch {};
                    return false;
                };
                // A layout is a shape, not a placement: the save path omits
                // window geometry deliberately. Strip any a hand-authored or
                // synced file carries so it cannot place the new window
                // off-screen, resize it, or maximize it.
                var shape = parsed.value.windows[0];
                shape.x = null;
                shape.y = null;
                shape.width = null;
                shape.height = null;
                shape.state = null;
                const surface = self.restoreSessionWindow(shape) catch |err| {
                    log.warn("named layout materialization failed name={s} err={}", .{ name, err });
                    if (banner_host) |host| host.setBanner(.err, "Layout could not be opened.") catch {};
                    return false;
                };
                self.activateSurface(surface);
                return true;
            },
        }
    }

    fn quarantineInvalidNamedLayout(
        self: *App,
        path: []const u8,
        name: []const u8,
        parse_error: anyerror,
    ) bool {
        const destination = win32_session_persistence.quarantineCorruptFileAlloc(
            self.core_app.alloc,
            path,
        ) catch |err| {
            log.warn("named layout quarantine failed name={s} path={s} parse_err={} move_err={}", .{ name, path, parse_error, err });
            return false;
        };
        defer self.core_app.alloc.free(destination);
        log.warn("named layout quarantined invalid file name={s} path={s} parse_err={}", .{ name, destination, parse_error });
        return true;
    }

    fn saveNamedLayout(self: *App, target: apprt.Target, name: []const u8) bool {
        const surface = self.findSurfaceForTarget(target) orelse {
            log.warn("named layout save has no target surface name={s}", .{name});
            return false;
        };
        const host = surface.host orelse {
            log.warn("named layout save target has no host name={s}", .{name});
            return false;
        };
        win32_layouts.validateName(name) catch |err| {
            log.warn("named layout save rejected invalid name name={s} err={}", .{ name, err });
            host.setBanner(.err, "Invalid layout name.") catch {};
            return false;
        };
        const path = self.namedLayoutPath(name) catch |err| {
            log.warn("named layout save path resolution failed name={s} err={}", .{ name, err });
            host.setBanner(.err, "Layout path is unavailable.") catch {};
            return false;
        };
        defer self.core_app.alloc.free(path);

        var arena = std.heap.ArenaAllocator.init(self.core_app.alloc);
        defer arena.deinit();
        const window = buildSessionWindow(arena.allocator(), host, .layout) catch |err| {
            log.warn("named layout save snapshot failed name={s} err={}", .{ name, err });
            host.setBanner(.err, "Layout could not be saved.") catch {};
            return false;
        };
        // Launch refuses documents above this cap, so refuse to write one.
        // Saving must not report success for a layout that can never open.
        win32_layouts.validateLaunchSize(window) catch |err| {
            log.warn("named layout save rejected oversized window name={s} err={}", .{ name, err });
            host.setBanner(.err, "Layout has too many tabs or panes.") catch {};
            return false;
        };
        const layout_windows = [_]win32_session_state.Window{window};
        const encoded = win32_session_state.encodeAlloc(
            self.core_app.alloc,
            .{ .windows = &layout_windows },
        ) catch |err| {
            log.warn("named layout save encode failed name={s} err={}", .{ name, err });
            host.setBanner(.err, "Layout could not be saved.") catch {};
            return false;
        };
        defer self.core_app.alloc.free(encoded);
        if (!namedLayoutEncodingFitsReadLimit(encoded.len)) {
            log.warn(
                "named layout save rejected oversized encoding name={s} bytes={d}",
                .{ name, encoded.len },
            );
            host.setBanner(.err, "Layout data is too large.") catch {};
            return false;
        }
        writePersistentFileAlloc(self.core_app.alloc, path, encoded) catch |err| {
            log.warn("named layout save write failed name={s} path={s} err={}", .{ name, path, err });
            host.setBanner(.err, "Layout could not be saved.") catch {};
            return false;
        };
        host.setBanner(.info, "Layout saved.") catch {};
        return true;
    }

    fn namedLayoutEncodingFitsReadLimit(bytes: usize) bool {
        return bytes <= win32_session_persistence.default_max_state_bytes;
    }

    fn restoreSessionState(self: *App) !bool {
        var parsed = self.loadSessionState() catch |err| {
            log.warn("win32 session restore: state read failed; leaving file untouched err={}", .{err});
            return false;
        } orelse return false;
        defer parsed.deinit();

        var restored = false;
        for (parsed.value.windows) |window| {
            if (self.restoreSessionWindow(window)) |surface| {
                restored = true;
                self.activateSurface(surface);
            } else |err| {
                log.warn("win32 session restore: skipped window err={}", .{err});
            }
        }

        return restored;
    }

    fn quarantineInvalidSessionState(self: *App, path: []const u8, parse_error: anyerror) void {
        const destination = win32_session_persistence.quarantineCorruptFileAlloc(
            self.core_app.alloc,
            path,
        ) catch |err| {
            log.warn("win32 session restore: quarantine failed path={s} parse_err={} move_err={}", .{ path, parse_error, err });
            return;
        };
        defer self.core_app.alloc.free(destination);
        log.warn("win32 session restore: quarantined unreadable state path={s} parse_err={}", .{ destination, parse_error });
    }

    fn markRecoveryReady(self: *App) void {
        if (self.recovery_startup.count == 0) return;
        const memory_attempts = self.recovery_startup.attempts[0..self.recovery_startup.count];
        const target_started_at = memory_attempts[memory_attempts.len - 1].started_at_unix_ms;
        if (memory_attempts[memory_attempts.len - 1].ready_at_unix_ms != null) return;

        var disk_record: win32_recovery.StartupAttemptRecord = .{};
        var parsed_record: ?std.json.Parsed(win32_recovery.StartupAttemptRecord) = null;
        defer if (parsed_record) |*parsed| parsed.deinit();
        if (localAppDataPathAlloc(self.core_app.alloc, "startup-attempts.json")) |path| {
            defer self.core_app.alloc.free(path);
            if (std.fs.openFileAbsolute(path, .{})) |file| {
                defer file.close();
                if (file.readToEndAlloc(self.core_app.alloc, 64 * 1024)) |raw| {
                    defer self.core_app.alloc.free(raw);
                    parsed_record = win32_recovery.parseAlloc(self.core_app.alloc, raw) catch |err| invalid: {
                        log.warn("win32 recovery: ready merge ignored invalid disk history err={}", .{err});
                        break :invalid null;
                    };
                    if (parsed_record) |*parsed| disk_record = parsed.value;
                } else |err| {
                    log.warn("win32 recovery: ready merge read failed err={}", .{err});
                }
            } else |err| switch (err) {
                error.FileNotFound => {},
                else => log.warn("win32 recovery: ready merge open failed err={}", .{err}),
            }
        }

        var merged_attempts: [win32_recovery.max_attempts]win32_recovery.StartupAttempt = undefined;
        const merged = win32_recovery.mergeMarkReady(
            disk_record,
            .{ .attempts = memory_attempts },
            target_started_at,
            unixMillis(),
            &merged_attempts,
        ) catch |err| {
            log.warn("win32 recovery: ready marker merge failed err={}", .{err});
            return;
        };
        @memcpy(self.recovery_startup.attempts[0..merged.attempts.len], merged.attempts);
        self.recovery_startup.count = merged.attempts.len;
        persistRecoveryRecord(
            self.core_app.alloc,
            self.recovery_startup.attempts[0..self.recovery_startup.count],
        ) catch |err| log.warn("win32 recovery: ready marker persist failed err={}", .{err});
    }

    fn restoreSessionWindow(
        self: *App,
        window: win32_session_state.Window,
    ) !*Surface {
        var transaction = SessionRestoreTransaction.init(self);
        defer transaction.rollback();
        var host: ?*Host = null;
        var window_surface: ?*Surface = null;

        for (window.tabs, 0..) |saved_tab, tab_index| {
            const tab_surface = try self.restoreSessionTab(
                saved_tab,
                host,
                tab_index,
                &transaction,
            );
            if (host == null) {
                host = tab_surface.host;
                if (host) |created_host| {
                    applyRestoredWindowPlacement(created_host, window) catch |err| {
                        log.warn("win32 session restore: window placement failed err={}", .{err});
                    };
                }
            }
            if (window_surface == null or tab_index == window.selected_tab) {
                window_surface = tab_surface;
            }
        }

        const restored_host = host orelse return error.EmptyTabs;
        if (restored_host.tabs.items.len == 0) return error.EmptyTabs;
        restored_host.active_tab = @min(window.selected_tab, restored_host.tabs.items.len - 1);
        const active_tab = &restored_host.tabs.items[restored_host.active_tab];
        const selected = active_tab.focusedSurface() orelse window_surface orelse return error.EmptyTabs;
        transaction.commit();
        return selected;
    }

    fn restoreSessionTab(
        self: *App,
        saved_tab: win32_session_state.Tab,
        existing_host: ?*Host,
        tab_index: usize,
        transaction: *SessionRestoreTransaction,
    ) !*Surface {
        var tab_surface: ?*Surface = null;
        var created: usize = 0;
        var selected_surface: ?*Surface = null;
        const node_surfaces = try self.core_app.alloc.alloc(?*Surface, saved_tab.layout.nodes.len);
        defer self.core_app.alloc.free(node_surfaces);
        @memset(node_surfaces, null);

        for (saved_tab.layout.nodes, 0..) |node, node_index| {
            const pane = switch (node) {
                .pane => |value| value,
                .split => continue,
            };
            const surface = try self.restoreSessionPane(
                pane,
                existing_host,
                tab_surface,
                tab_index,
                preferredSplitDirection(saved_tab.layout),
                transaction,
            );
            node_surfaces[node_index] = surface;
            if (tab_surface == null) tab_surface = surface;
            if (created == saved_tab.selected_leaf) selected_surface = surface;
            created += 1;
        }

        const first = tab_surface orelse return error.EmptyLayout;
        const selected = selected_surface orelse first;
        if (self.findTabForSurface(selected)) |found| {
            var restored_tree = try buildRestoredSessionSplitTree(
                self.core_app.alloc,
                saved_tab.layout,
                node_surfaces,
            );
            errdefer restored_tree.deinit();

            found.tab.tree.deinit();
            found.tab.tree = restored_tree;
            if (found.tab.findHandle(selected)) |handle| found.tab.focused = handle;
            try found.host.layout();
        }
        return selected;
    }

    fn restoreSessionPane(
        self: *App,
        pane: win32_session_state.Pane,
        existing_host: ?*Host,
        tab_surface: ?*Surface,
        tab_index: usize,
        split_direction: SplitTreeSurface.Split.Direction,
        transaction: *SessionRestoreTransaction,
    ) !*Surface {
        const host = existing_host orelse if (tab_surface) |source| source.host else null;
        const open_kind: apprt.surface.NewSurfaceContext = if (host == null)
            .window
        else if (tab_surface == null)
            .tab
        else
            .split;
        var config = try apprt.surface.newConfig(self.core_app, &self.config, open_kind);
        defer config.deinit();

        // `initial-command` (from `-e` or the config option) applies to the
        // ordinary first window. A restored pane's command comes from its
        // saved profile, so clear it: otherwise `Surface.init` prefers it
        // while `app.first` is set and the first pane of a restored session
        // or a launched layout runs the wrong command.
        config.@"initial-command" = null;

        // A refused profile (today: SSH) must not leave its key on the surface
        // either, or a later split of the restored pane would re-resolve it and
        // launch the connection this restore just declined.
        const profile_applied = if (pane.profile) |key|
            try self.applyRestoredProfileConfig(&config, host, key)
        else
            false;
        if (pane.cwd) |cwd| {
            const alloc = config._arena.?.allocator();
            config.@"working-directory" = .{ .path = try alloc.dupe(u8, cwd) };
        }

        const tab_id = if (tab_surface) |source|
            (self.findTabForSurface(source) orelse return error.NoActiveSurface).tab.id
        else
            null;
        const surface = try self.createWindowSurface(&config, default_title, .{
            .host_id = if (host) |existing| existing.id else null,
            .tab_id = tab_id,
            .tab_insert_index = if (host != null and tab_surface == null) tab_index else null,
            .clone_state_from = tab_surface,
            .split_direction = split_direction,
        });
        transaction.noteSurface(surface);

        if (profile_applied) {
            try appendOwnedString(self.core_app.alloc, &surface.launch_profile_key, pane.profile.?);
        }
        if (pane.title_override) |title| try surface.setTitleOverride(title);
        if (pane.tab_title_override) |title| try surface.setTabTitleOverride(title);
        if (pane.cwd) |cwd| try surface.setPwd(cwd);
        return surface;
    }

    fn applyRestoredProfileConfig(
        self: *App,
        config: *configpkg.Config,
        host: ?*Host,
        key: []const u8,
    ) !bool {
        if (host) |existing| {
            const profile = (try existing.profileForKey(key)) orelse return false;
            if (!isSessionRestorableProfile(profile)) return false;
            try applyProfileSurfaceConfig(config, profile);
            return true;
        }

        const profiles = try windows_shell.listProfiles(
            self.core_app.alloc,
            self.config.@"ssh-config-hosts",
        );
        defer windows_shell.deinitProfiles(self.core_app.alloc, profiles);
        return try applyProfileConfigByKey(config, profiles, key);
    }

    fn applyRestoredWindowPlacement(
        host: *Host,
        window: win32_session_state.Window,
    ) !void {
        const hwnd = host.hwnd orelse return;
        if (try sessionStateWindowRect(window)) |rect| {
            if (sys.SetWindowPos(
                hwnd,
                null,
                rect.left,
                rect.top,
                rect.right - rect.left,
                rect.bottom - rect.top,
                c.SWP_NOZORDER | c.SWP_NOACTIVATE,
            ) == 0) return lastError();
        }
        if ((window.state orelse .normal) == .maximized) {
            _ = sys.ShowWindow(hwnd, c.SW_MAXIMIZE);
        }
    }

    fn saveSessionState(self: *const App) bool {
        if (!self.sessionStateEnabled()) return false;
        const path = self.sessionStatePath() orelse return false;
        defer self.core_app.alloc.free(path);

        var arena = std.heap.ArenaAllocator.init(self.core_app.alloc);
        defer arena.deinit();
        const alloc = arena.allocator();

        const state = self.buildSessionState(alloc) catch |err| {
            log.warn("win32 session save: snapshot failed err={}", .{err});
            return false;
        };
        if (state.windows.len == 0) {
            win32_session_persistence.deleteFileIfPresent(path) catch |err| {
                log.warn("win32 session save: delete stale state failed path={s} err={}", .{ path, err });
                return false;
            };
            return true;
        }

        const encoded = win32_session_state.encodeAlloc(self.core_app.alloc, state) catch |err| {
            log.warn("win32 session save: encode failed err={}", .{err});
            return false;
        };
        defer self.core_app.alloc.free(encoded);

        writePersistentFileAlloc(self.core_app.alloc, path, encoded) catch |err| {
            log.warn("win32 session save: write failed path={s} err={}", .{ path, err });
            return false;
        };
        return true;
    }

    fn buildSessionState(
        self: *const App,
        alloc: Allocator,
    ) !win32_session_state.SessionState {
        var count: usize = 0;
        for (self.hosts.items) |host| {
            if (hostSessionTabCount(host) > 0) count += 1;
        }

        const windows_state = try alloc.alloc(win32_session_state.Window, count);
        var built: usize = 0;
        for (self.hosts.items) |host| {
            if (hostSessionTabCount(host) == 0) continue;
            windows_state[built] = try buildSessionWindow(alloc, host, .session);
            built += 1;
        }

        return .{ .windows = windows_state };
    }

    /// What a window snapshot is for. `.session` is this process's own restore
    /// state; `.layout` is a user-visible named layout file, which carries only
    /// the shape fields and no window geometry.
    const SnapshotScope = enum { session, layout };

    fn buildSessionWindow(
        alloc: Allocator,
        host: *Host,
        scope: SnapshotScope,
    ) !win32_session_state.Window {
        const tab_count = hostSessionTabCount(host);
        if (scope == .layout and tab_count == 0) return error.EmptyTabs;
        const tabs = try alloc.alloc(win32_session_state.Tab, tab_count);
        var selected_tab: usize = 0;
        var built: usize = 0;
        for (host.tabs.items, 0..) |*tab, i| {
            if (tabContainsQuickTerminal(tab)) continue;
            if (i <= host.active_tab) selected_tab = built;
            tabs[built] = try buildSessionTab(alloc, tab, scope);
            built += 1;
        }

        var window: win32_session_state.Window = .{
            .selected_tab = selected_tab,
            .tabs = tabs,
        };
        // Geometry is restore state, not layout shape.
        if (scope == .layout) return window;
        if (sessionWindowRect(host)) |rect| {
            window.x = rect.left;
            window.y = rect.top;
            window.width = rect.right - rect.left;
            window.height = rect.bottom - rect.top;
        }
        if (host.hwnd) |hwnd| {
            window.state = if (sys.IsZoomed(hwnd) != 0) .maximized else .normal;
        }
        return window;
    }

    fn buildSessionTab(
        alloc: Allocator,
        tab: *const Tab,
        scope: SnapshotScope,
    ) !win32_session_state.Tab {
        var selected_leaf: usize = 0;
        var leaf_index: usize = 0;
        for (tab.tree.nodes, 0..) |node, node_index| {
            switch (node) {
                .leaf => {},
                .split => continue,
            }
            if (tab.focused.idx() == node_index) selected_leaf = leaf_index;
            leaf_index += 1;
        }

        return .{
            .selected_leaf = selected_leaf,
            .layout = try buildSessionLayout(alloc, tab, scope),
        };
    }

    fn buildSessionLayout(
        alloc: Allocator,
        tab: *const Tab,
        scope: SnapshotScope,
    ) !win32_session_state.LayoutTree {
        if (tab.tree.nodes.len > std.math.maxInt(u16)) return error.TooManySessionLayoutNodes;
        const nodes = try alloc.alloc(win32_session_state.Node, tab.tree.nodes.len);
        for (tab.tree.nodes, 0..) |node, i| {
            nodes[i] = switch (node) {
                // The two pane literals are deliberately separate. Anything
                // added to the session pane below (terminal contents, process
                // state) must stay out of user-visible layout files unless it
                // is also added to the layout literal on purpose. Neither
                // snapshot may persist an SSH launch for unattended restore.
                .leaf => |surface| switch (scope) {
                    .session => .{ .pane = .{
                        .cwd = if (surface.launched_ssh) null else surface.pwd,
                        .profile = if (surface.launched_ssh) null else surface.launch_profile_key,
                        .title_override = surface.title_override,
                        .tab_title_override = if (surface.launched_ssh)
                            null
                        else
                            surface.tab_title_override,
                    } },
                    .layout => .{ .pane = .{
                        .cwd = if (surface.launched_ssh) null else surface.pwd,
                        .profile = if (surface.launched_ssh) null else surface.launch_profile_key,
                        .title_override = surface.title_override,
                        .tab_title_override = if (surface.launched_ssh)
                            null
                        else
                            surface.tab_title_override,
                    } },
                },
                .split => |split| .{ .split = .{
                    .axis = switch (split.layout) {
                        .horizontal => .horizontal,
                        .vertical => .vertical,
                    },
                    .ratio = @floatCast(split.ratio),
                    .first = @intFromEnum(split.left),
                    .second = @intFromEnum(split.right),
                } },
            };
        }
        return .{ .root = 0, .nodes = nodes };
    }

    fn hostContainsQuickTerminal(host: *const Host) bool {
        for (host.tabs.items) |*tab| {
            if (tabContainsQuickTerminal(tab)) return true;
        }
        return false;
    }

    fn hostSessionTabCount(host: *const Host) usize {
        var count: usize = 0;
        for (host.tabs.items) |*tab| {
            if (!tabContainsQuickTerminal(tab)) count += 1;
        }
        return count;
    }

    fn tabContainsQuickTerminal(tab: *const Tab) bool {
        var it = tab.tree.iterator();
        while (it.next()) |entry| {
            if (entry.view.quick_terminal) return true;
        }
        return false;
    }

    fn preferredSplitDirection(
        layout: win32_session_state.LayoutTree,
    ) SplitTreeSurface.Split.Direction {
        if (layout.root < layout.nodes.len) {
            switch (layout.nodes[layout.root]) {
                .split => |split| return switch (split.axis) {
                    .horizontal => .right,
                    .vertical => .down,
                },
                .pane => {},
            }
        }
        return .right;
    }

    fn buildRestoredSessionSplitTree(
        alloc: Allocator,
        layout: win32_session_state.LayoutTree,
        node_surfaces: []const ?*Surface,
    ) (Allocator.Error || error{ InvalidTreeShape, TooManySessionLayoutNodes })!SplitTreeSurface {
        if (layout.nodes.len == 0 or layout.nodes.len != node_surfaces.len) {
            return error.InvalidTreeShape;
        }
        if (layout.root >= layout.nodes.len) return error.InvalidTreeShape;
        if (layout.nodes.len > std.math.maxInt(SplitTreeSurface.Node.Handle.Backing)) {
            return error.TooManySessionLayoutNodes;
        }

        const invalid_index = std.math.maxInt(usize);
        const remap = try alloc.alloc(usize, layout.nodes.len);
        defer alloc.free(remap);
        @memset(remap, invalid_index);

        if (layout.root == 0) {
            for (remap, 0..) |*slot, i| slot.* = i;
        } else {
            const stack = try alloc.alloc(usize, layout.nodes.len);
            defer alloc.free(stack);

            remap[layout.root] = 0;
            stack[0] = layout.root;
            var stack_len: usize = 1;
            var next_index: usize = 1;
            while (stack_len > 0) {
                stack_len -= 1;
                const saved_index = stack[stack_len];
                switch (layout.nodes[saved_index]) {
                    .pane => {},
                    .split => |split| {
                        const children = [_]u16{ split.first, split.second };
                        for (children) |child| {
                            const child_index: usize = child;
                            if (child_index >= layout.nodes.len) return error.InvalidTreeShape;
                            if (remap[child_index] == invalid_index) {
                                remap[child_index] = next_index;
                                next_index += 1;
                                stack[stack_len] = child_index;
                                stack_len += 1;
                            }
                        }
                    },
                }
            }
            if (next_index != layout.nodes.len) return error.InvalidTreeShape;
        }

        var arena = std.heap.ArenaAllocator.init(alloc);
        errdefer arena.deinit();
        const tree_nodes = try arena.allocator().alloc(SplitTreeSurface.Node, layout.nodes.len);

        for (layout.nodes, 0..) |node, saved_index| {
            const restored_index = remap[saved_index];
            if (restored_index == invalid_index) return error.InvalidTreeShape;
            tree_nodes[restored_index] = switch (node) {
                .pane => .{ .leaf = node_surfaces[saved_index] orelse return error.InvalidTreeShape },
                .split => |split| .{ .split = .{
                    .layout = switch (split.axis) {
                        .horizontal => .horizontal,
                        .vertical => .vertical,
                    },
                    .ratio = @floatCast(split.ratio),
                    .left = @enumFromInt(remap[split.first]),
                    .right = @enumFromInt(remap[split.second]),
                } },
            };
        }

        return .{
            .arena = arena,
            .nodes = tree_nodes,
            .zoomed = null,
        };
    }

    fn sessionStateWindowRect(window: win32_session_state.Window) !?RECT {
        const x = window.x orelse {
            if (window.y == null and window.width == null and window.height == null) return null;
            return error.InvalidWindowRect;
        };
        const y = window.y orelse return error.InvalidWindowRect;
        const width = window.width orelse return error.InvalidWindowRect;
        const height = window.height orelse return error.InvalidWindowRect;
        if (width <= 0 or height <= 0) return error.InvalidWindowRect;
        const right = std.math.add(i32, x, width) catch return error.InvalidWindowRect;
        const bottom = std.math.add(i32, y, height) catch return error.InvalidWindowRect;
        return .{
            .left = x,
            .top = y,
            .right = right,
            .bottom = bottom,
        };
    }

    fn sessionWindowRect(host: *Host) ?RECT {
        const hwnd = host.hwnd orelse return null;
        var rect: RECT = undefined;
        if (sys.IsZoomed(hwnd) != 0 or sys.IsIconic(hwnd) != 0) {
            var placement: WINDOWPLACEMENT = .{
                .length = @sizeOf(WINDOWPLACEMENT),
                .flags = 0,
                .showCmd = 0,
                .ptMinPosition = .{ .x = 0, .y = 0 },
                .ptMaxPosition = .{ .x = 0, .y = 0 },
                .rcNormalPosition = .{ .left = 0, .top = 0, .right = 0, .bottom = 0 },
            };
            if (sys.GetWindowPlacement(hwnd, &placement) != 0) {
                rect = placement.rcNormalPosition;
            } else if (sys.GetWindowRect(hwnd, &rect) == 0) {
                return null;
            }
        } else if (sys.GetWindowRect(hwnd, &rect) == 0) {
            return null;
        }

        if (rect.right <= rect.left or rect.bottom <= rect.top) return null;
        return rect;
    }

    /// Push an action string onto the palette MRU list, dedup'd by
    /// exact match, rotating the oldest slot out. `action` is not owned
    /// by the caller; this dups it into the app allocator. Safe to call
    /// with an action that may be the same as an existing MRU entry —
    /// that entry is moved to the front without reallocating.
    fn pushPaletteMru(self: *App, action: []const u8) !void {
        // If action already exists, move it to slot 0.
        var existing_index: ?usize = null;
        for (self.palette_mru, 0..) |slot, i| {
            if (slot) |owned| {
                if (std.mem.eql(u8, owned, action)) {
                    existing_index = i;
                    break;
                }
            }
        }
        if (existing_index) |i| {
            if (i == 0) return;
            const top = self.palette_mru[i];
            var j: usize = i;
            while (j > 0) : (j -= 1) self.palette_mru[j] = self.palette_mru[j - 1];
            self.palette_mru[0] = top;
            return;
        }
        // Insert as new head. Free whatever falls off the end.
        const duped = try self.core_app.alloc.dupeZ(u8, action);
        errdefer self.core_app.alloc.free(duped);
        if (self.palette_mru[self.palette_mru.len - 1]) |oldest| {
            self.core_app.alloc.free(oldest);
        }
        var j: usize = self.palette_mru.len - 1;
        while (j > 0) : (j -= 1) self.palette_mru[j] = self.palette_mru[j - 1];
        self.palette_mru[0] = duped;
    }

    /// View of the MRU list as a slice of non-null entries, newest first.
    /// Shared storage; caller must not free or retain past the next
    /// `pushPaletteMru` call.
    fn paletteMruSlice(self: *const App, buf: *[5][]const u8) []const []const u8 {
        var n: usize = 0;
        for (self.palette_mru) |slot| {
            if (slot) |owned| {
                buf[n] = owned;
                n += 1;
            }
        }
        return buf[0..n];
    }

    fn tryForwardStartupToExistingInstance(self: *App) !bool {
        if (self.config.@"single-instance" != .true) return false;

        const pipe_name = try self.resolveIpcPipeName(self.core_app.alloc);
        defer self.core_app.alloc.free(pipe_name);

        if (try trySendStartupLaunchLayoutIpc(
            self.core_app.alloc,
            pipe_name,
            self.config.@"launch-layout",
        )) |forwarded| return forwarded;

        const arguments = try collectStartupForwardArguments(self.core_app.alloc);
        defer win32_ipc.freeOwnedArguments(self.core_app.alloc, arguments);

        return try sendNewWindowIpc(
            self.core_app.alloc,
            pipe_name,
            arguments,
        );
    }

    fn startIpcServer(self: *App) !void {
        if (self.config.@"single-instance" != .true) return;
        if (self.ipc_thread != null) return;

        self.ipc_pipe_name = try self.resolveIpcPipeName(self.core_app.alloc);
        errdefer {
            if (self.ipc_pipe_name) |pipe_name| self.core_app.alloc.free(pipe_name);
            self.ipc_pipe_name = null;
        }

        self.ipc_stop_requested.store(false, .release);
        self.ipc_thread = try std.Thread.spawn(.{}, ipcServerMain, .{self});
    }

    fn resolveIpcPipeName(self: *const App, alloc: Allocator) ![:0]const u16 {
        return allocIpcPipeName(alloc, self.config.class);
    }

    fn stopIpcServer(self: *App) void {
        if (self.ipc_thread) |thread| {
            self.ipc_stop_requested.store(true, .release);
            if (self.ipc_pipe_name) |pipe_name| {
                if (connectToIpcPipe(pipe_name)) |pipe| {
                    _ = windows.CloseHandle(pipe);
                } else |_| {}
            }
            thread.join();
            self.ipc_thread = null;
        }

        if (self.ipc_pipe_name) |pipe_name| {
            self.core_app.alloc.free(pipe_name);
            self.ipc_pipe_name = null;
        }
        self.ipc_stop_requested.store(false, .release);
    }

    fn unregisterGlobalHotkeys(self: *App) void {
        for (self.global_hotkeys.items) |hotkey| {
            _ = sys.UnregisterHotKey(null, hotkey.id);
        }
        self.global_hotkeys.clearRetainingCapacity();
    }

    fn syncGlobalHotkeys(self: *App) !void {
        self.unregisterGlobalHotkeys();

        var next_id: i32 = 1;
        var it = self.config.keybind.set.bindings.iterator();
        while (it.next()) |entry| {
            const generic = switch (entry.value_ptr.*) {
                .leader => continue,
                .leaf => |*leaf| leaf.generic(),
                .leaf_chained => |*leaf| leaf.generic(),
            };
            if (!generic.flags.global) continue;

            const spec = hotkeySpecForTrigger(entry.key_ptr.*) orelse {
                log.warn("skipping unsupported win32 global hotkey trigger={f}", .{entry.key_ptr.*});
                continue;
            };

            if (self.registeredGlobalHotkeyForSpec(spec)) |existing| {
                log.warn("skipping duplicate win32 global hotkey trigger={f} conflicts_with={f} mods=0x{x} vk=0x{x}", .{
                    entry.key_ptr.*,
                    existing.trigger,
                    spec.modifiers,
                    spec.vk,
                });
                continue;
            }

            if (sys.RegisterHotKey(null, next_id, spec.modifiers, spec.vk) == 0) {
                const err = windows.kernel32.GetLastError();
                log.warn("failed to register win32 global hotkey trigger={f} id={} mods=0x{x} vk=0x{x} err={} reason={s}", .{
                    entry.key_ptr.*,
                    next_id,
                    spec.modifiers,
                    spec.vk,
                    err,
                    hotkeyRegistrationFailureReason(err),
                });
                continue;
            }

            try self.global_hotkeys.append(self.core_app.alloc, .{
                .id = next_id,
                .trigger = entry.key_ptr.*,
                .spec = spec,
                .binding = entry.value_ptr,
            });
            next_id += 1;
        }
    }

    fn registeredGlobalHotkeyForSpec(self: *const App, spec: GlobalHotkeySpec) ?RegisteredGlobalHotkey {
        for (self.global_hotkeys.items) |hotkey| {
            if (hotkeySpecEql(hotkey.spec, spec)) return hotkey;
        }
        return null;
    }

    fn scheduleGlobalHotkeySync(self: *App) void {
        self.global_hotkeys_dirty = true;
        self.wakeup();
    }

    fn handleGlobalHotkey(self: *App, id: i32) void {
        for (self.global_hotkeys.items) |hotkey| {
            if (hotkey.id != id) continue;

            switch (hotkey.binding.*) {
                .leader => unreachable,
                .leaf => |*leaf| self.core_app.performAllChainedAction(self, leaf.generic().actionsSlice()),
                .leaf_chained => |*leaf| self.core_app.performAllChainedAction(self, leaf.generic().actionsSlice()),
            }
            return;
        }
    }

    pub fn wakeup(self: *App) void {
        if (self.windows.items.len > 0) {
            const hwnd = self.windows.items[0].hwnd orelse return;
            _ = sys.PostMessageW(hwnd, c.WM_WINHOSTTY_WAKE, 0, 0);
            return;
        }

        if (self.ui_thread_id != 0) {
            _ = sys.PostThreadMessageW(self.ui_thread_id, c.WM_WINHOSTTY_WAKE, 0, 0);
        }
    }

    fn maybeScheduleAutomaticUpdateCheck(self: *App) void {
        if (self.update_auto_check_started) return;
        if (self.config.@"auto-update" == .off) return;
        if (self.config.@"auto-update-channel" != .stable) return;
        if (self.ui_thread_id == 0) return;

        self.update_auto_check_started = true;
        self.scheduleUpdateCheck(.{
            .force = false,
            .manual = false,
            .respect_dismissal = true,
        }) catch |err| {
            log.warn("failed to start automatic update check err={}", .{err});
        };
    }

    fn scheduleUpdateCheck(
        self: *App,
        opts: struct {
            force: bool,
            manual: bool,
            respect_dismissal: bool,
        },
    ) !void {
        if (self.ui_thread_id == 0) return;

        const current = self.update_check_running.cmpxchgStrong(false, true, .acq_rel, .acquire);
        if (current != null) {
            if (opts.manual) try self.showUpdateInfo("Update check already running.");
            return;
        }
        errdefer self.update_check_running.store(false, .release);

        const request = try self.core_app.alloc.create(UpdateCheckRequest);
        errdefer self.core_app.alloc.destroy(request);

        request.* = .{
            .alloc = self.core_app.alloc,
            .ui_thread_id = self.ui_thread_id,
            .state_path = try updatepkg.defaultStatePath(self.core_app.alloc),
            .current_version = build_config.version,
            .current_version_string = try self.core_app.alloc.dupe(u8, build_config.version_string),
            .force = opts.force,
            .manual = opts.manual,
            .respect_dismissal = opts.respect_dismissal,
            .download = self.config.@"auto-update" == .download,
        };

        const thread = try std.Thread.spawn(.{}, updateCheckThreadMain, .{request});
        thread.detach();
    }

    fn handleUpdateCheckCompletion(self: *App, completion: *UpdateCheckCompletion) void {
        self.update_check_running.store(false, .release);

        if (completion.release) |release| {
            self.setUpdateNotice(release.version_text, release.release_url, completion.staged) catch |err| {
                log.warn("failed to surface update notice err={}", .{err});
            };
            if (completion.manual_message) |message| {
                self.showUpdateInfo(message) catch |err| {
                    log.warn("failed to show updater status message err={}", .{err});
                };
            }
            return;
        }

        if (completion.manual_message) |message| {
            self.showUpdateInfo(message) catch |err| {
                log.warn("failed to show updater status message err={}", .{err});
            };
        }
    }

    fn setUpdateNotice(self: *App, version_text: []const u8, release_url: []const u8, staged: bool) !void {
        if (self.update_notice) |*notice| {
            if (ownedBytesEquals(notice.version_text, version_text) and
                ownedBytesEquals(notice.release_url, release_url) and
                notice.staged == staged)
            {
                return;
            }
            notice.deinit(self.core_app.alloc);
            self.update_notice = null;
        }

        self.update_notice = try UpdateNotice.init(self.core_app.alloc, version_text, release_url, staged);
        for (self.hosts.items) |host| host.invalidateBannerText();
    }

    fn clearUpdateNotice(self: *App) void {
        if (self.update_notice) |*notice| {
            notice.deinit(self.core_app.alloc);
            self.update_notice = null;
            for (self.hosts.items) |host| host.invalidateBannerText();
        }
    }

    fn openUpdateNotice(self: *App) !void {
        const notice = self.update_notice orelse return;
        if (notice.staged) {
            if (!self.canApplyStagedUpdate()) {
                if (notice.release_url) |url| {
                    try self.openUrl(url);
                    return;
                }
            }
            try self.applyStagedUpdate();
            return;
        }
        try self.openUrl(notice.release_url.?);
    }

    fn dismissUpdateNotice(self: *App) void {
        const notice = self.update_notice orelse return;
        if (notice.staged) {
            self.clearUpdateNotice();
            return;
        }

        const version_text = notice.version_text orelse {
            self.clearUpdateNotice();
            return;
        };

        const state_path = updatepkg.defaultStatePath(self.core_app.alloc) catch |err| {
            log.warn("failed to resolve updater state path err={}", .{err});
            self.clearUpdateNotice();
            return;
        };
        defer self.core_app.alloc.free(state_path);

        updatepkg.recordDismissal(self.core_app.alloc, state_path, version_text) catch |err| {
            log.warn("failed to record updater dismissal err={}", .{err});
        };
        self.clearUpdateNotice();
    }

    fn applyStagedUpdate(self: *App) !void {
        const state_path = try updatepkg.defaultStatePath(self.core_app.alloc);
        defer self.core_app.alloc.free(state_path);

        var staged = updatepkg.verifyStagedWindowsInstall(self.core_app.alloc, state_path) catch |err| {
            self.showUpdateInfo(updateApplyFailureMessage(err)) catch |banner_err| {
                log.warn("failed to show updater apply failure err={}", .{banner_err});
            };
            return err;
        };
        defer staged.deinit(self.core_app.alloc);

        const install_dir = currentInstallDir(self.core_app.alloc) catch |err| {
            self.showUpdateInfo(updateApplyFailureMessage(err)) catch |banner_err| {
                log.warn("failed to show updater apply failure err={}", .{banner_err});
            };
            return err;
        };
        defer self.core_app.alloc.free(install_dir);

        if (!isInstallerManagedInstallDir(install_dir)) {
            self.showUpdateInfo(updateApplyFailureMessage(error.PortableInstallUpdateApplyUnsupported)) catch |banner_err| {
                log.warn("failed to show updater apply failure err={}", .{banner_err});
            };
            return error.PortableInstallUpdateApplyUnsupported;
        }

        const stage_dir = std.fs.path.dirname(staged.installer_path) orelse return error.InvalidStagedInstallerPath;
        const logs_dir = try std.fs.path.join(self.core_app.alloc, &.{ stage_dir, "logs" });
        defer self.core_app.alloc.free(logs_dir);
        try std.fs.cwd().makePath(logs_dir);

        const log_path = try std.fs.path.join(self.core_app.alloc, &.{ logs_dir, "apply.log" });
        defer self.core_app.alloc.free(log_path);

        const params = try buildInstallerApplyArgs(self.core_app.alloc, install_dir, log_path);
        defer self.core_app.alloc.free(params);

        const installer_w = try std.unicode.utf8ToUtf16LeAllocZ(self.core_app.alloc, staged.installer_path);
        defer self.core_app.alloc.free(installer_w);
        const params_w = try std.unicode.utf8ToUtf16LeAllocZ(self.core_app.alloc, params);
        defer self.core_app.alloc.free(params_w);
        const stage_dir_w = try std.unicode.utf8ToUtf16LeAllocZ(self.core_app.alloc, stage_dir);
        defer self.core_app.alloc.free(stage_dir_w);

        const result = sys.ShellExecuteW(
            null,
            shell_runas,
            installer_w.ptr,
            params_w.ptr,
            stage_dir_w.ptr,
            c.SW_SHOW,
        );
        if (@intFromPtr(result) <= 32) {
            self.showUpdateInfo(updateApplyFailureMessage(error.UpdateApplyLaunchFailed)) catch |banner_err| {
                log.warn("failed to show updater apply failure err={}", .{banner_err});
            };
            return error.UpdateApplyLaunchFailed;
        }

        updatepkg.recordStagedApplyRequested(self.core_app.alloc, state_path, 0) catch |err| {
            log.warn("failed to record updater apply request after launch err={}", .{err});
        };

        self.stopQuitTimer();
        self.running = false;
        self.destroyAllWindows();
        if (self.windows.items.len == 0) sys.PostQuitMessage(0);
    }

    fn canApplyStagedUpdate(self: *App) bool {
        const install_dir = currentInstallDir(self.core_app.alloc) catch return false;
        defer self.core_app.alloc.free(install_dir);
        return isInstallerManagedInstallDir(install_dir);
    }

    fn showUpdateInfo(self: *App, message: []const u8) !void {
        if (self.primarySurface()) |surface| {
            if (surface.host) |host| {
                try host.setBanner(.info, message);
                return;
            }
        }
        try showInfoMessage(.app, "noctty", message);
    }

    /// True when any user-facing top-level UI window is still alive —
    /// either a terminal Host or the settings window. The quit timer
    /// and message-loop exit check both use this so the app doesn't
    /// tear down while the settings window holds an unsaved pending
    /// draft. Palette / confirm overlays are owned by their Host and
    /// therefore don't need their own count.
    fn hasLiveUiWindows(self: *const App) bool {
        if (self.windows.items.len != 0) return true;
        if (self.settings_window.hwnd != null) return true;
        return false;
    }

    pub fn startQuitTimer(self: *App) void {
        if (!self.running) return;
        if (self.hasLiveUiWindows()) {
            self.stopQuitTimer();
            return;
        }
        if (!self.config.@"quit-after-last-window-closed") {
            self.stopQuitTimer();
            return;
        }

        const delay = self.config.@"quit-after-last-window-closed-delay" orelse {
            self.stopQuitTimer();
            self.running = false;
            sys.PostQuitMessage(0);
            return;
        };

        self.stopQuitTimer();
        const delay_ms = quitTimerDelayMs(delay);
        const timer_id = sys.SetTimer(null, 0, delay_ms, null);
        if (timer_id == 0) {
            log.err("failed to start win32 quit timer delay_ms={} err={}", .{
                delay_ms,
                windows.kernel32.GetLastError(),
            });
            return;
        }
        self.quit_timer_id = timer_id;
    }

    fn stopQuitTimer(self: *App) void {
        if (self.quit_timer_id) |timer_id| {
            _ = sys.KillTimer(null, timer_id);
            self.quit_timer_id = null;
        }
    }

    fn stopUndoPruneTimer(self: *App) void {
        if (self.undo_prune_timer_id) |timer_id| {
            _ = sys.KillTimer(null, timer_id);
            self.undo_prune_timer_id = null;
        }
    }

    fn undoTimeoutMs(self: *const App) u64 {
        return std.math.divCeil(
            u64,
            self.config.@"undo-timeout".duration,
            std.time.ns_per_ms,
        ) catch std.math.maxInt(u64);
    }

    fn nextUndoSequence(self: *App) u64 {
        const sequence = self.next_undo_sequence;
        self.next_undo_sequence +%= 1;
        if (self.next_undo_sequence == 0) self.next_undo_sequence = 1;
        return sequence;
    }

    fn oldestUndoTimestamp(self: *const App) ?u64 {
        var oldest: ?u64 = null;
        for (self.windows.items) |surface| {
            if (surface.undo_stack.oldestTimestamp()) |timestamp| {
                if (oldest == null or timestamp < oldest.?) oldest = timestamp;
            }
        }
        for (self.hosts.items) |host| {
            if (host.oldestStructuralTimestamp()) |timestamp| {
                if (oldest == null or timestamp < oldest.?) oldest = timestamp;
            }
        }
        return oldest;
    }

    fn scheduleUndoPruneTimer(self: *App) void {
        self.scheduleUndoPruneTimerWithMinimum(1);
    }

    fn scheduleUndoPruneTimerWithMinimum(self: *App, minimum_delay_ms: u64) void {
        if (!self.running) return;
        self.stopUndoPruneTimer();

        const oldest = self.oldestUndoTimestamp() orelse return;
        const now = sys.GetTickCount64();
        const expires_at = oldest +| self.undoTimeoutMs() +| 1;
        const delay_ms = @max(minimum_delay_ms, if (expires_at <= now) 1 else expires_at - now);
        const timer_id = sys.SetTimer(
            null,
            0,
            @intCast(@min(delay_ms, std.math.maxInt(UINT))),
            null,
        );
        if (timer_id == 0) {
            log.warn("failed to start win32 undo prune timer err={}", .{
                windows.kernel32.GetLastError(),
            });
            return;
        }
        self.undo_prune_timer_id = timer_id;
    }

    fn pruneUndoHistoryBefore(self: *App, min_timestamp_ms: u64) bool {
        var complete = true;
        for (self.windows.items) |surface| {
            surface.undo_stack.discardExpired(min_timestamp_ms);
        }

        var i: usize = 0;
        while (i < self.hosts.items.len) {
            const host = self.hosts.items[i];
            if (!host.pruneStructuralHistoryBefore(min_timestamp_ms)) complete = false;
            if (host.destroy_after_structural_dispose and host.tabs.items.len == 0 and !host.hasStructuralHistory()) {
                if (host.hwnd) |hwnd| {
                    _ = sys.DestroyWindow(hwnd);
                    self.removeHost(host);
                    continue;
                }
                host.destroy_after_structural_dispose = false;
            }
            if (i < self.hosts.items.len and self.hosts.items[i] == host) {
                i += 1;
            }
        }
        return complete;
    }

    fn pruneUndoHistoryNow(self: *App) void {
        const complete = self.pruneUndoHistoryBefore(self.undoCutoffTimestampMs());
        if (complete)
            self.scheduleUndoPruneTimer()
        else
            self.scheduleUndoPruneTimerWithMinimum(1000);
        if (self.running and !self.hasLiveUiWindows()) self.startQuitTimer();
    }

    fn ensureMessageQueue() void {
        var msg: MSG = undefined;
        _ = sys.PeekMessageW(&msg, null, 0, 0, c.PM_NOREMOVE);
    }

    pub fn performAction(
        self: *App,
        target: apprt.Target,
        comptime action: apprt.Action.Key,
        value: apprt.Action.Value(action),
    ) !bool {
        switch (action) {
            .quit => {
                self.stopQuitTimer();
                self.running = false;
                self.destroyAllWindows();
                if (self.windows.items.len == 0) sys.PostQuitMessage(0);
                return true;
            },

            .new_window => {
                var forwarded_arguments = value.arguments;
                switch (scanForwardedToastActivation(value.arguments)) {
                    .none => {},
                    .malformed => {
                        std.log.warn("dropping malformed forwarded toast activation argv", .{});
                        return true;
                    },
                    .activation => |activation| {
                        const dropped_args = forwardedActivationExtraArgCount(value.arguments);
                        if (dropped_args > 0) {
                            std.log.warn("dropping {d} forwarded argv item(s) bundled with toast activation", .{dropped_args});
                        }
                        if (self.handleToastActivation(activation)) return true;
                        self.pending_toast_activation = activation;
                        forwarded_arguments = null;
                    },
                }
                var config = try apprt.surface.newConfig(
                    self.core_app,
                    &self.config,
                    .window,
                );
                defer config.deinit();
                // The forwarded argv reaches us over the single-instance IPC
                // pipe, so it is only as trusted as any process running as
                // this user. Refuse the whole request unless every key is on
                // the presentation allowlist.
                if (forwarded_arguments) |argv| {
                    if (forwardedArgvRejection(argv)) |rejection| {
                        logForwardedArgvRejection(rejection);
                        return true;
                    }
                }
                applyNewWindowArguments(
                    self.core_app.alloc,
                    &config,
                    forwarded_arguments,
                ) catch |err| switch (err) {
                    // Defense in depth: `applyNewWindowArguments` enforces
                    // the same filter independently. Treat a rejection as
                    // handled so it cannot abort the app tick. Logged here
                    // too so the rejection can never become silent if the
                    // pre-check above is ever refactored away.
                    error.ForbiddenForwardedArgument => {
                        log.err(
                            "refusing forwarded new-window argv: rejected by applyNewWindowArguments",
                            .{},
                        );
                        return true;
                    },
                    else => return err,
                };
                if (config.@"launch-layout") |name| {
                    const banner_host = if (self.findSurfaceForTarget(target)) |source| source.host else null;
                    _ = self.launchNamedLayout(name, banner_host);
                    return true;
                }
                _ = try self.createWindowSurface(&config, default_title, .{
                    .clone_state_from = self.findSurfaceForTarget(target),
                });
                return true;
            },

            .launch_layout => {
                const banner_host = if (self.findSurfaceForTarget(target)) |source| source.host else null;
                return layoutActionResult(self.launchNamedLayout(value.name, banner_host));
            },

            .save_layout => {
                return layoutActionResult(self.saveNamedLayout(target, value.name));
            },

            .new_tab => {
                var config = try apprt.surface.newConfig(
                    self.core_app,
                    &self.config,
                    .tab,
                );
                defer config.deinit();
                const source = self.findSurfaceForTarget(target);
                const surface = try self.createWindowSurface(&config, default_title, .{
                    .host_id = if (source) |v| v.host_id else null,
                    .tab_insert_index = if (source) |v| if (v.host) |host|
                        windowNewTabInsertIndex(host, self.config.@"window-new-tab-position")
                    else
                        null else null,
                    .clone_state_from = source,
                });
                if (source) |v| {
                    v.invalidateRedoForUnsupportedTabStructuralAction();
                }
                self.activateSurface(surface);
                return true;
            },

            .new_split => {
                var config = try apprt.surface.newConfig(
                    self.core_app,
                    &self.config,
                    .split,
                );
                defer config.deinit();
                const source = self.findSurfaceForTarget(target) orelse return false;
                const tab_info = self.findTabForSurface(source) orelse return false;
                const inherited_profile_key = try applySplitProfileConfigFromSource(&config, source);
                if (shouldInheritSplitWorkingDirectory(source.launched_ssh)) {
                    _ = try applySplitWorkingDirectoryFromSource(&config, source, self.startup_cwd);
                }
                const split_direction = splitDirectionFromAction(value);
                const surface = try self.createWindowSurface(&config, default_title, .{
                    .host_id = source.host_id,
                    .tab_id = tab_info.tab.id,
                    .clone_state_from = source,
                    .split_direction = split_direction,
                });
                if (inherited_profile_key) |key| {
                    try appendOwnedString(self.core_app.alloc, &surface.launch_profile_key, key);
                    surface.launched_ssh = source.launched_ssh;
                }
                tab_info.tab.clearRedoHistory();
                if (tab_info.host.pushStructuralUndo(.{
                    .kind = .split_create,
                    .timestamp_ms = sys.GetTickCount64(),
                    .sequence_id = self.nextUndoSequence(),
                    .payload = .{ .split_create = .{
                        .source_surface = source,
                        .created_surface = surface,
                        .direction = split_direction,
                    } },
                })) |_| {} else |err| {
                    log.warn("new_split undo snapshot failed err={}", .{err});
                    _ = tab_info.host.clearStructuralRedo();
                }
                self.activateSurface(surface);
                return true;
            },

            .close_tab => {
                return try self.closeTab(target, value);
            },

            .close_all_windows => {
                self.stopQuitTimer();
                self.running = false;
                self.destroyAllWindows();
                if (self.windows.items.len == 0) sys.PostQuitMessage(0);
                return true;
            },

            .close_window => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    if (surface.host) |host| host.close();
                    return true;
                }

                return false;
            },

            .config_change => {
                switch (target) {
                    .app => {
                        var config = try value.config.clone(self.core_app.alloc);
                        const ssh_config_hosts_changed =
                            self.config.@"ssh-config-hosts" != config.@"ssh-config-hosts";
                        // CLI launch-layout is a one-shot startup/new-window
                        // request. Config reload reparses the original argv, so
                        // strip it before installing the long-lived app config
                        // -- both the parsed field and the replay step, since
                        // a later theme or conditional-state reload would
                        // otherwise put it back.
                        config.@"launch-layout" = null;
                        _ = config.dropLaunchLayoutReplaySteps(0);
                        // Palette theme preview owns a reversible baseline
                        // around the app-global config. An external/settings
                        // config change supersedes that transaction: dismiss
                        // the palette first so it reverts and resets every
                        // borrowed catalog before the incoming config replaces
                        // the baseline. A later Escape can never resurrect the
                        // stale pre-reload config.
                        for (self.hosts.items) |host| {
                            if (host.overlay_mode == .command_palette) host.hideOverlay();
                        }
                        self.unregisterGlobalHotkeys();
                        self.config.deinit();
                        self.config = config;
                        self.config_revision +%= 1;
                        if (self.config_revision == 0) self.config_revision = 1;
                        for (self.hosts.items) |host| {
                            if (ssh_config_hosts_changed) {
                                host.invalidateProfiles();
                                if (host.overlay_mode == .profile) {
                                    _ = host.reloadProfiles() catch |err| blk: {
                                        log.warn("SSH profile reload after config change failed err={}", .{err});
                                        break :blk false;
                                    };
                                }
                            }
                            if (host.overlay_mode == .command_palette) host.rebuildPaletteList();
                        }
                        self.scheduleGlobalHotkeySync();
                        self.reconfigureTheme();
                        for (self.windows.items) |surface| {
                            try surface.applyRuntimeConfig(&self.config);
                        }
                        self.settings_window.externalConfigChanged(&self.config, self.config_revision);
                        if (self.windows.items.len == 0) {
                            self.startQuitTimer();
                        } else {
                            self.stopQuitTimer();
                        }
                    },
                    .surface => |core_surface| {
                        const surface = self.findSurfaceByCore(core_surface) orelse return false;
                        try surface.applyRuntimeConfig(value.config);
                        try self.syncHostWindowState(surface);
                    },
                }
                return true;
            },

            .reload_config => {
                if (target != .app) return false;
                if (value.soft) {
                    try self.core_app.updateConfig(self, &self.config);
                    if (self.config.@"app-notifications".@"config-reload") {
                        try self.showDesktopNotification(.app, "noctty", "Configuration reloaded");
                    }
                    return true;
                }

                // Same startup-cwd restoration dance as
                // `settingsSaveAndReload`: `Config.load` calls
                // `loadCliArgs`, which realpaths `--config-file
                // <relative>` against current cwd. After
                // `sanitizeCurrentDirectory()` ran, relative overrides
                // would resolve to a different file than launch used,
                // silently swapping the config source on every manual
                // reload. Scoped to this path — non-reload code keeps
                // seeing the sanitized cwd.
                const cwd_before: ?[]u8 = std.process.getCwdAlloc(self.core_app.alloc) catch null;
                defer if (cwd_before) |p| self.core_app.alloc.free(p);

                // `defer` + flag so the restore fires even when
                // `Config.load` returns an error — otherwise a
                // broken include leaves the process pinned to
                // `startup_cwd` (same class of bug as the one
                // fixed in `settingsSaveAndReload`). Relative-path
                // lookups + child processes spawned after a failed
                // reload would inherit the wrong cwd.
                var did_chdir_to_startup: bool = false;
                if (self.startup_cwd) |cwd| {
                    if (std.process.changeCurDir(cwd)) |_| {
                        did_chdir_to_startup = true;
                    } else |err| {
                        std.log.warn("reload_config: couldn't restore startup cwd path={s} err={}", .{ cwd, err });
                    }
                }
                defer {
                    if (did_chdir_to_startup) {
                        if (cwd_before) |cwd| {
                            std.process.changeCurDir(cwd) catch |err| {
                                std.log.warn("reload_config: couldn't restore sanitized cwd path={s} err={}", .{ cwd, err });
                            };
                        }
                    }
                }

                var config = try configpkg.Config.load(self.core_app.alloc);
                defer config.deinit();
                try self.core_app.updateConfig(self, &config);
                if (self.config.@"app-notifications".@"config-reload") {
                    try self.showDesktopNotification(.app, "noctty", "Configuration reloaded");
                }
                return true;
            },

            .present_terminal, .color_change, .mouse_over_link => {
                if (action == .present_terminal) {
                    if (self.findSurfaceForTarget(target)) |surface| {
                        surface.present();
                        return true;
                    }
                    return false;
                }
                return true;
            },

            .renderer_health => {
                const surface = self.findSurfaceForTarget(target) orelse return false;
                return surface.handleRendererHealth(value);
            },

            .quit_timer => {
                if (target != .app) return false;
                switch (value) {
                    .start => self.startQuitTimer(),
                    .stop => self.stopQuitTimer(),
                }
                return true;
            },

            .toggle_visibility => {
                self.windows_hidden = !self.windows_hidden;
                if (self.windows_hidden) {
                    for (self.hosts.items) |host| host.setVisible(false);
                } else {
                    for (self.hosts.items) |host| {
                        host.setVisible(true);
                        try host.layout();
                    }
                    if (self.findSurfaceForTarget(target)) |surface| {
                        self.activateSurface(surface);
                    } else if (self.primarySurface()) |surface| {
                        self.activateSurface(surface);
                    }
                }
                return true;
            },

            .toggle_background_opacity => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    const changed = try surface.toggleBackgroundOpacity();
                    if (!changed) return false;
                    try self.syncHostWindowState(surface);
                    return true;
                }
                return false;
            },

            .goto_window => {
                return try self.gotoWindow(target, value);
            },

            .goto_split => {
                return try self.gotoSplitFallback(target, value);
            },

            .resize_split => {
                return try self.resizeSplitFallback(target, value);
            },

            .equalize_splits => {
                return try self.equalizeSplitsFallback(target);
            },

            .move_tab => {
                return try self.moveTab(target, value);
            },

            .goto_tab => {
                return try self.gotoTab(target, value);
            },

            .toggle_tab_overview => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    return try surface.toggleTabOverview();
                }
                return false;
            },

            .toggle_quick_terminal => {
                try self.toggleQuickTerminal();
                return true;
            },

            .toggle_maximize => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    surface.toggleMaximize();
                    try self.syncHostWindowState(surface);
                    return true;
                }
                return false;
            },

            .toggle_fullscreen => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.toggleFullscreen(value);
                    try self.syncHostWindowState(surface);
                    return true;
                }
                return false;
            },

            .toggle_window_decorations => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.toggleDecorations();
                    try self.syncHostWindowState(surface);
                    return true;
                }
                return false;
            },

            .float_window => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setFloatWindow(value);
                    try self.syncHostWindowState(surface);
                    return true;
                }
                return false;
            },

            .initial_size => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setInitialSize(value);
                    try self.syncHostWindowState(surface);
                    return true;
                }
                return false;
            },

            .reset_window_size => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.resetWindowSize();
                    try self.syncHostWindowState(surface);
                    return true;
                }
                return false;
            },

            .size_limit => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    surface.setSizeLimit(value);
                    try self.syncHostWindowState(surface);
                    return true;
                }
                return false;
            },

            .cell_size => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    surface.setCellSize(value);
                    try self.syncHostWindowState(surface);
                    return true;
                }
                return false;
            },

            .toggle_split_zoom => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    const found = self.findTabForSurface(surface) orelse return false;
                    const handle = found.tab.findHandle(surface) orelse found.tab.focused;
                    found.tab.tree.zoom(if (found.tab.tree.zoomed != null) null else handle);
                    surface.invalidateRedoForUnsupportedTabStructuralAction();
                    try found.host.layout();
                    return true;
                }
                return false;
            },

            .render => {
                return switch (target) {
                    .app => blk: {
                        for (self.windows.items) |surface| {
                            try surface.requestRepaintWithMode(rendererRepaintRequestMode(surface.host));
                            surface.drainTerminalAccessibilityOutput();
                            if (surface.terminal_accessibility) |session| session.rendererUpdated();
                        }
                        break :blk true;
                    },
                    .surface => if (self.findSurfaceForTarget(target)) |surface| blk: {
                        try surface.requestRepaintWithMode(rendererRepaintRequestMode(surface.host));
                        surface.drainTerminalAccessibilityOutput();
                        if (surface.terminal_accessibility) |session| session.rendererUpdated();
                        break :blk true;
                    } else false,
                };
            },

            .render_inspector => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    surface.redrawInspector();
                    return true;
                }

                return false;
            },

            .inspector => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    return try self.setInspectorActionForSurface(surface, value);
                }
                return false;
            },

            .show_gtk_inspector => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    return try self.setInspectorActionForSurface(surface, .show);
                }
                return false;
            },

            .set_title => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setTitle(value.title);
                    return true;
                }

                return false;
            },

            .set_tab_title => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setTabTitleOverride(if (value.title.len == 0) null else value.title);
                    return true;
                }

                return false;
            },

            .prompt_title => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.promptTitle(value);
                    return true;
                }

                return false;
            },

            .toggle_command_palette => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    return try surface.toggleCommandPalette();
                }
                return false;
            },

            .pwd => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setPwd(value.pwd);
                    return true;
                }

                return false;
            },

            .mouse_shape => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    surface.setMouseShape(value);
                    return true;
                }
                return false;
            },

            .mouse_visibility => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    surface.setMouseVisibility(value);
                    return true;
                }
                return false;
            },

            .progress_report => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setProgressReport(value);
                    return true;
                }
                return false;
            },

            .command_finished => {
                try self.showCommandFinished(target, value);
                return true;
            },

            .start_search => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.showSearchOverlay(value.needle);
                    return true;
                }
                return false;
            },

            .end_search => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.closeDockedSearchBar(false, false);
                    return true;
                }
                return false;
            },

            .search_total => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setSearchTotal(value.total);
                    return true;
                }
                return false;
            },

            .search_selected => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setSearchSelected(value.selected);
                    return true;
                }
                return false;
            },

            .search_match_rows => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setSearchMatchRows(value.rows);
                    return true;
                }
                return false;
            },

            .secure_input => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setSecureInput(value);
                    return true;
                }
                return false;
            },

            .readonly => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setReadonly(value == .on);
                    return true;
                }
                return false;
            },

            .key_sequence => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setKeySequenceActive(switch (value) {
                        .trigger => true,
                        .end => false,
                    });
                    return true;
                }
                return false;
            },

            .key_table => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setKeyTable(value);
                    return true;
                }
                return false;
            },

            .scrollbar => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    try surface.setScrollbar(value);
                    return true;
                }
                return false;
            },

            .undo => {
                self.pruneUndoHistoryNow();
                const surface = self.undoRedoSurfaceForTarget(target) orelse {
                    const host = self.structuralUndoHostForTarget(target) orelse return false;
                    while (host.peekStructuralUndo() != null) {
                        const message = try host.applyLatestStructuralUndo() orelse continue;
                        try host.setBanner(.info, message);
                        return true;
                    }
                    try host.setBanner(.info, "Nothing to undo.");
                    return true;
                };

                while (true) {
                    const host_entry = if (surface.host) |host| host.peekStructuralUndo() else null;
                    const local_entry = surface.undo_stack.peekUndo();

                    if (host_entry == null and local_entry == null) break;
                    const use_host = host_entry != null and
                        (local_entry == null or win32_structural_history.sortsAfter(
                            host_entry.?.timestamp_ms,
                            host_entry.?.sequence_id,
                            local_entry.?.timestamp_ms,
                            local_entry.?.sequence_id,
                        ));

                    if (use_host) {
                        const host = surface.host orelse break;
                        const message = try host.applyLatestStructuralUndo() orelse continue;
                        _ = try self.showHostBanner(.{ .surface = surface.core() }, .info, message);
                        return true;
                    }

                    const message = try surface.applyLatestLocalUndo() orelse continue;
                    _ = try self.showHostBanner(.{ .surface = surface.core() }, .info, message);
                    return true;
                }

                _ = try self.showHostBanner(.{ .surface = surface.core() }, .info, "Nothing to undo.");
                return true;
            },

            .redo => {
                self.pruneUndoHistoryNow();
                const surface = self.undoRedoSurfaceForTarget(target) orelse {
                    const host = self.structuralRedoHostForTarget(target) orelse return false;
                    while (host.peekStructuralRedo() != null) {
                        const message = try host.applyLatestStructuralRedo() orelse continue;
                        try host.setBanner(.info, message);
                        return true;
                    }
                    try host.setBanner(.info, "Nothing to redo.");
                    return true;
                };

                while (true) {
                    const host_entry = if (surface.host) |host| host.peekStructuralRedo() else null;
                    const local_entry = surface.undo_stack.peekRedo();

                    if (host_entry == null and local_entry == null) break;
                    const use_host = host_entry != null and
                        (local_entry == null or win32_structural_history.sortsAfter(
                            host_entry.?.timestamp_ms,
                            host_entry.?.sequence_id,
                            local_entry.?.timestamp_ms,
                            local_entry.?.sequence_id,
                        ));

                    if (use_host) {
                        const host = surface.host orelse break;
                        const message = try host.applyLatestStructuralRedo() orelse continue;
                        _ = try self.showHostBanner(.{ .surface = surface.core() }, .info, message);
                        return true;
                    }

                    const message = try surface.applyLatestLocalRedo() orelse continue;
                    _ = try self.showHostBanner(.{ .surface = surface.core() }, .info, message);
                    return true;
                }

                _ = try self.showHostBanner(.{ .surface = surface.core() }, .info, "Nothing to redo.");
                return true;
            },

            .check_for_updates => {
                if (self.config.@"auto-update-channel" != .stable) {
                    _ = try self.showHostBanner(target, .info, "Automatic prerelease update checks are not supported yet. Opening releases.");
                    try self.openUrl(releases_url);
                    return true;
                }

                try self.scheduleUpdateCheck(.{
                    .force = true,
                    .manual = true,
                    .respect_dismissal = false,
                });
                return true;
            },

            .open_url => {
                try self.openUrl(value.url);
                return true;
            },

            .show_on_screen_keyboard => {
                try self.showOnScreenKeyboard();
                return true;
            },

            .open_config => {
                try self.openConfig();
                return true;
            },

            .copy_title_to_clipboard => {
                if (self.findSurfaceForTarget(target)) |surface| {
                    const title = surface.getTitle() orelse return false;
                    try surface.writeClipboardText(title);
                    return true;
                }
                return false;
            },

            .ring_bell => {
                self.ringBell(target);
                return true;
            },

            .desktop_notification => {
                try self.showDesktopNotification(target, value.title, value.body);
                return true;
            },

            .show_child_exited => {
                try self.showChildExited(target, value);
                return true;
            },
        }
    }

    pub fn performIpc(
        alloc: Allocator,
        target: apprt.ipc.Target,
        comptime action: apprt.ipc.Action.Key,
        value: apprt.ipc.Action.Value(action),
    ) !bool {
        switch (action) {
            .new_window => {
                const launch_layout = scanLaunchLayoutIpcArgument(value.arguments) catch |err| {
                    log.err("--launch-layout must be the only +new-window argument", .{});
                    return err;
                };

                const pipe_name = try resolveIpcPipeNameForTarget(alloc, target);
                defer alloc.free(pipe_name);
                const forwarded = switch (launch_layout) {
                    .none => try sendNewWindowIpc(alloc, pipe_name, value.arguments),
                    .name => |name| try sendLaunchLayoutIpc(alloc, pipe_name, name),
                };
                if (forwarded) return true;
                return try spawnWindowProcess(alloc, target, value);
            },
        }
    }

    pub fn queryAutomationWindowList(
        alloc: Allocator,
        target: apprt.ipc.Target,
    ) !?[]u8 {
        const pipe_name = try resolveIpcPipeNameForTarget(alloc, target);
        defer alloc.free(pipe_name);
        return try sendListWindowsIpc(alloc, pipe_name);
    }

    pub fn performAutomationAction(
        alloc: Allocator,
        target: apprt.ipc.Target,
        action_target: apprt.ipc.AutomationActionTarget,
        action_text: []const u8,
    ) !bool {
        const pipe_name = try resolveIpcPipeNameForTarget(alloc, target);
        defer alloc.free(pipe_name);
        return try sendPerformActionIpc(alloc, pipe_name, action_target, action_text);
    }

    pub fn buildAutomationWindowListJson(
        self: *App,
        alloc: Allocator,
    ) ![]u8 {
        var snapshot = try self.buildAutomationWindowList(alloc);
        defer snapshot.deinit(alloc);

        var buf: std.Io.Writer.Allocating = .init(alloc);
        errdefer buf.deinit();
        try buf.writer.print("{f}", .{std.json.fmt(snapshot, .{})});
        return try buf.toOwnedSlice();
    }

    fn buildAutomationWindowList(
        self: *App,
        alloc: Allocator,
    ) !apprt.ipc.AutomationWindowList {
        const window_entries = try alloc.alloc(apprt.ipc.AutomationWindow, self.automationWindowCount());
        var built: usize = 0;
        errdefer {
            for (window_entries[0..built]) |*window| window.deinit(alloc);
            alloc.free(window_entries);
        }

        for (self.hosts.items) |host| {
            if (host.tabs.items.len == 0) continue;
            window_entries[built] = try buildAutomationWindow(alloc, host);
            built += 1;
        }

        return .{ .windows = window_entries };
    }

    fn automationWindowCount(self: *const App) usize {
        var count: usize = 0;
        for (self.hosts.items) |host| {
            if (host.tabs.items.len == 0) continue;
            count += 1;
        }
        return count;
    }

    fn buildAutomationWindow(
        alloc: Allocator,
        host: *Host,
    ) !apprt.ipc.AutomationWindow {
        const tabs = try alloc.alloc(apprt.ipc.AutomationTab, host.tabs.items.len);
        var built: usize = 0;
        errdefer {
            for (tabs[0..built]) |*tab| tab.deinit(alloc);
            alloc.free(tabs);
        }

        var active_tab_id: ?u32 = null;
        for (host.tabs.items, 0..) |*tab, i| {
            const active = i == host.active_tab;
            tabs[i] = try buildAutomationTab(alloc, tab, active);
            if (active) active_tab_id = tab.id;
            built += 1;
        }

        return .{
            .window_id = host.id,
            .focused = if (host.activeSurface()) |surface| surface.window_focused else false,
            .active_tab_id = active_tab_id,
            .tab_count = @intCast(tabs.len),
            .pane_count = automationPaneCount(tabs),
            .tabs = tabs,
        };
    }

    fn buildAutomationTab(
        alloc: Allocator,
        tab: *const Tab,
        active: bool,
    ) !apprt.ipc.AutomationTab {
        var panes: std.ArrayList(apprt.ipc.AutomationPane) = .empty;
        defer panes.deinit(alloc);

        const focused_surface = tab.focusedSurface();
        var it = tab.tree.iterator();
        while (it.next()) |entry| {
            try panes.append(alloc, .{
                .surface_id = entry.view.core().id,
                .focused = if (focused_surface) |surface| surface == entry.view else false,
                // True only for the focused pane in the active tab, not every
                // tab-local focused pane.
                .active = active and (if (focused_surface) |surface| surface == entry.view else false),
            });
        }

        return .{
            .tab_id = tab.id,
            .active = active,
            .focused_surface_id = if (focused_surface) |surface| surface.core().id else null,
            .pane_count = @intCast(panes.items.len),
            .panes = try panes.toOwnedSlice(alloc),
        };
    }

    fn automationPaneCount(tabs: []const apprt.ipc.AutomationTab) u64 {
        var count: u64 = 0;
        for (tabs) |tab| count += @intCast(tab.panes.len);
        return count;
    }

    fn spawnWindowProcess(
        alloc: Allocator,
        target: apprt.ipc.Target,
        value: apprt.ipc.Action.NewWindow,
    ) !bool {
        const exe_path = try std.fs.selfExePathAlloc(alloc);
        defer alloc.free(exe_path);

        var argv: std.ArrayList([]const u8) = .empty;
        defer argv.deinit(alloc);

        try argv.append(alloc, exe_path);
        if (target == .class) {
            const class_arg = try std.fmt.allocPrint(alloc, "--class={s}", .{target.class});
            defer alloc.free(class_arg);
            try argv.append(alloc, class_arg);
        }
        if (value.arguments) |arguments| {
            for (arguments) |arg| try argv.append(alloc, arg);
        }

        var child = std.process.Child.init(argv.items, alloc);
        child.stdin_behavior = .Ignore;
        child.stdout_behavior = .Ignore;
        child.stderr_behavior = .Ignore;
        try child.spawn();
        return true;
    }

    fn ensureWindowClass(self: *App) !void {
        if (self.class_atom != 0) return;

        var wc: WNDCLASSEXW = .{
            .cbSize = @sizeOf(WNDCLASSEXW),
            .style = c.CS_OWNDC,
            .lpfnWndProc = &windowProc,
            .cbClsExtra = 0,
            .cbWndExtra = 0,
            .hInstance = self.hinstance,
            .hIcon = loadAppIcon(self.hinstance, false),
            .hCursor = sys.LoadCursorW(null, c.IDC_ARROW),
            .hbrBackground = null,
            .lpszMenuName = null,
            .lpszClassName = class_name,
            .hIconSm = loadAppIcon(self.hinstance, true),
        };

        self.class_atom = sys.RegisterClassExW(&wc);
        if (self.class_atom == 0) {
            return lastError();
        }
    }

    fn ensureHostWindowClass(self: *App) !void {
        if (self.host_class_atom != 0) return;

        var wc: WNDCLASSEXW = .{
            .cbSize = @sizeOf(WNDCLASSEXW),
