    var created: Surface = undefined;
    var session: TestSession = .{};
    try session.init(.{
        .core_app = &core_app,
        .app = &app,
        .hosts = &.{.{ .storage = &host, .register = true, .next_tab_id = 3 }},
        .surfaces = &.{
            .{ .storage = &source, .host = &host, .register = true },
            .{ .storage = &sibling, .host = &host, .register = true },
