    Hook.created_ref = &created;
    app.test_create_window_surface = &Hook.createSurface;

    const profile: windows_shell.Profile = .{
        .kind = .pwsh,
        .key = "pwsh",
        .label = "PowerShell",
        .command = .{ .direct = &.{"pwsh.exe"} },
    };

