    core_app.first = false;
    rolled_back.rollback();
    try std.testing.expect(core_app.first);

    var committed = SessionRestoreTransaction.init(&app);
    core_app.first = false;
    committed.commit();
    committed.rollback();
    try std.testing.expect(!core_app.first);
}

