        try std.testing.expect(actions.cancel_x >= 0);
        try std.testing.expect(actions.cancel_width > 0);
        try std.testing.expect(actions.cancel_x + actions.cancel_width <= width);
        try std.testing.expectEqual(
            OverlayFocusSlot.cancel,
            nextVisibleOverlayFocusSlot(
                .confirm,
                .edit,
                false,
                false,
                actions.accept_visible,
                actions.cancel_visible,
            ),
        );
        if (width < 140) {
            const expected_inset = @min(@as(i32, 10), @divTrunc(width - 1, 2));
            try std.testing.expect(actions.compact_cancel);
            try std.testing.expectEqual(expected_inset, actions.cancel_x);
            try std.testing.expectEqual(width - 2 * expected_inset, actions.cancel_width);
        } else {
            try std.testing.expect(!actions.compact_cancel);
            try std.testing.expectEqual(@as(i32, 80), actions.cancel_width);
        }
    }

    const wide = overlayActionLayoutForWidth(.confirm, 230, 10, 80, 80, 96);
    try std.testing.expect(wide.accept_visible);
    try std.testing.expect(wide.cancel_visible);
    try std.testing.expect(!wide.compact_cancel);
    try std.testing.expect(wide.accept_x >= 0);
    try std.testing.expect(wide.accept_x + wide.accept_width <= wide.cancel_x);
    try std.testing.expect(wide.cancel_x + wide.cancel_width <= 230);
}

test "win32 overlay buttons activate only for their exact click notification" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    const accept: HWND = @ptrFromInt(0x10);
    const cancel: HWND = @ptrFromInt(0x20);
    try std.testing.expect(expectedButtonClick(c.BN_CLICKED, accept, accept));
    try std.testing.expect(!expectedButtonClick(c.BN_SETFOCUS, accept, accept));
    try std.testing.expect(!expectedButtonClick(c.BN_KILLFOCUS, accept, accept));
    try std.testing.expect(!expectedButtonClick(c.BN_CLICKED, cancel, accept));
    try std.testing.expect(!expectedButtonClick(c.BN_CLICKED, null, accept));
}

test "win32 palette theme preview can restore original config clone" {
    var original = try configpkg.Config.default(std.testing.allocator);
    defer original.deinit();
    try Host.setConfigTheme(&original, "Original Theme");

    var preview = try original.clone(std.testing.allocator);
    defer preview.deinit();
    try Host.setConfigTheme(&preview, "Preview Theme");
    try std.testing.expectEqualStrings("Preview Theme", preview.theme.?.light);
    try std.testing.expectEqualStrings("Original Theme", original.theme.?.light);

    var restored = try original.clone(std.testing.allocator);
    defer restored.deinit();
    try std.testing.expectEqualStrings("Original Theme", restored.theme.?.light);
}

test "win32 palette theme commit mutates pending without losing rollback source" {
    var original = try configpkg.Config.default(std.testing.allocator);
    defer original.deinit();
    try Host.setConfigTheme(&original, "Original Theme");

    var pending = try original.clone(std.testing.allocator);
    defer pending.deinit();
    try Host.setConfigTheme(&pending, "Committed Theme");

    try std.testing.expectEqualStrings("Original Theme", original.theme.?.light);
    try std.testing.expectEqualStrings("Committed Theme", pending.theme.?.light);
}

test "win32 rich palette completion cycles duplicate display text by stable id" {
    var items: [2]PaletteItem = undefined;
    var payloads: [2]PalettePayload = undefined;
    var catalog = try PaletteCatalog.init(&items, &payloads);
    try catalog.append(.{
        .item = .{
            .id = win32_palette.catalog.stableStringId(.tab, "tab-one"),
            .title = "Same title",
            .keywords = "same",
        },
        .payload = .{ .tab = 1 },
    });
    try catalog.append(.{
        .item = .{
            .id = win32_palette.catalog.stableStringId(.tab, "tab-two"),
            .title = "Same title",
            .keywords = "same",
        },
        .payload = .{ .tab = 2 },
    });

    var host: Host = undefined;
    host.palette_catalog = catalog;
    const first = host.richPaletteCompletionCandidate("same", "same", null, false).?;
    const second = host.richPaletteCompletionCandidate("same", first.text, first.id, false).?;
    try std.testing.expectEqualStrings("Same title", first.text);
    try std.testing.expectEqualStrings("Same title", second.text);
    try std.testing.expect(!first.id.eql(second.id));
}

test "win32 desiredTabIndex cycles and clamps" {
    if (builtin.os.tag != .windows) return error.SkipZigTest;

    try std.testing.expectEqual(@as(?usize, 0), desiredTabIndex(3, 1, .previous));
    try std.testing.expectEqual(@as(?usize, 2), desiredTabIndex(3, 0, .previous));
    try std.testing.expectEqual(@as(?usize, 2), desiredTabIndex(3, 1, .next));
    try std.testing.expectEqual(@as(?usize, 0), desiredTabIndex(3, 2, .next));
    try std.testing.expectEqual(@as(?usize, 2), desiredTabIndex(3, 0, .last));
    try std.testing.expectEqual(@as(?usize, 0), desiredTabIndex(3, 1, @enumFromInt(0)));
    try std.testing.expectEqual(@as(?usize, 2), desiredTabIndex(3, 1, @enumFromInt(9)));
}

